# Round 54 -- part28 rows 6-41; 29 items
BATCH={
  (28, 6): {
   "topic": "bbtProgesterone",
   "lead": "\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0647\u0648\u0631\u0645\u0648\u0646 \u06af\u0631\u0645\u0627\u0632\u0627 \u0633\u06cc\u06a9\u0644 \u0642\u0627\u0639\u062f\u06af\u06cc \u0627\u0633\u062a \u0648 \u067e\u0633 \u0627\u0632 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u062f\u0645\u0627\u06cc \u067e\u0627\u06cc\u0647\u0654 \u0628\u062f\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f.",
   "interpretation": "\u062f\u0631 \u0646\u06cc\u0645\u0647\u0654 \u062f\u0648\u0645 \u0633\u06cc\u06a9\u0644 (\u0641\u0627\u0632 \u0644\u0648\u062a\u0626\u0627\u0644)\u060c \u062c\u0633\u0645 \u0632\u0631\u062f \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062a\u0631\u0634\u062d \u0645\u06cc\u200c\u06a9\u0646\u062f \u06a9\u0647 \u0627\u062b\u0631 \u0645\u0648\u0644\u062f \u06af\u0631\u0645\u0627 \u0628\u0631 \u0645\u0631\u06a9\u0632 \u062a\u0646\u0638\u06cc\u0645 \u062f\u0645\u0627\u06cc \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633 \u062f\u0627\u0631\u062f \u0648 \u062f\u0645\u0627\u06cc \u067e\u0627\u06cc\u0647\u0654 \u0628\u062f\u0646 \u0631\u0627 \u062d\u062f\u0648\u062f \u06f0\u066b\u06f3 \u062a\u0627 \u06f0\u066b\u06f5 \u062f\u0631\u062c\u0647\u0654 \u0633\u0627\u0646\u062a\u06cc\u200c\u06af\u0631\u0627\u062f \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f\u061b \u0647\u0645\u06cc\u0646 \u062e\u0627\u0635\u06cc\u062a \u0645\u0628\u0646\u0627\u06cc \u0631\u0648\u0634 \u062b\u0628\u062a \u062f\u0645\u0627\u06cc \u067e\u0627\u06cc\u0647\u0654 \u0628\u062f\u0646 \u0628\u0631\u0627\u06cc \u0627\u0633\u062a\u0646\u0628\u0627\u0637 \u0648\u0642\u0648\u0639 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0627\u0633\u062a. \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u063a\u0627\u0644\u0628 \u0641\u0627\u0632 \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644\u0627\u0631 \u0627\u0633\u062a \u0648 GnRH \u0648 \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u200c\u0647\u0627 \u0645\u062d\u0631\u06a9\u200c\u0647\u0627\u06cc \u0645\u062d\u0648\u0631 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633-\u0647\u06cc\u067e\u0648\u0641\u06cc\u0632\u0627\u0646\u062f\u061b \u0647\u06cc\u0686\u200c\u06a9\u062f\u0627\u0645 \u0627\u062b\u0631 \u06af\u0631\u0645\u0627\u0632\u0627\u06cc\u06cc \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062c\u0633\u0645 \u0632\u0631\u062f \u0627\u062b\u0631 \u06af\u0631\u0645\u0627\u0632\u0627 \u062f\u0627\u0631\u062f \u0648 \u062f\u0645\u0627\u06cc \u067e\u0627\u06cc\u0647\u0654 \u0628\u062f\u0646 \u0631\u0627 \u062f\u0631 \u0641\u0627\u0632 \u0644\u0648\u062a\u0626\u0627\u0644 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0641\u0627\u0632 \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644\u0627\u0631 \u0631\u0627 \u0647\u062f\u0627\u06cc\u062a \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0631\u0648\u06cc \u062f\u0645\u0627\u06cc \u067e\u0627\u06cc\u0647 \u0627\u062b\u0631 \u06af\u0631\u0645\u0627\u0632\u0627 \u0646\u062f\u0627\u0631\u062f.", "GnRH \u062a\u0631\u0634\u062d \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u200c\u0647\u0627 \u0631\u0627 \u06a9\u0646\u062a\u0631\u0644 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u06af\u0631\u0645\u0627\u0632\u0627 \u0646\u06cc\u0633\u062a.", "FSH \u0648 LH \u0631\u0634\u062f \u0641\u0648\u0644\u06cc\u06a9\u0648\u0644 \u0648 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u0631\u0627 \u0647\u062f\u0627\u06cc\u062a \u0645\u06cc\u200c\u06a9\u0646\u0646\u062f \u0648 \u062f\u0645\u0627\u06cc \u0628\u062f\u0646 \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0646\u0645\u06cc\u200c\u062f\u0647\u0646\u062f."],
  },
  (28, 7): {
   "topic": "ashermanSyndrome",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647 \u067e\u0633 \u0627\u0632 \u06a9\u0648\u0631\u062a\u0627\u0698 \u0628\u0627 \u0647\u0648\u0631\u0645\u0648\u0646\u200c\u0647\u0627\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0648 \u062a\u0633\u062a \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0646\u0641\u06cc: \u0633\u0646\u062f\u0631\u0645 \u0622\u0634\u0631\u0645\u0646 \u062f\u0631 \u0635\u062f\u0631 \u0627\u062d\u062a\u0645\u0627\u0644\u0627\u062a \u0627\u0633\u062a.",
   "interpretation": "\u0633\u0627\u0628\u0642\u0647\u0654 \u06a9\u0648\u0631\u062a\u0627\u0698 \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0633\u0628\u0628 \u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u062c\u062f\u0627\u0631\u0647\u200c\u0647\u0627\u06cc \u0631\u062d\u0645 (\u0686\u0633\u0628\u0646\u062f\u06af\u06cc \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc) \u0634\u0648\u062f \u0648 \u0628\u0627 \u0648\u062c\u0648\u062f \u0647\u0648\u0631\u0645\u0648\u0646\u200c\u0647\u0627\u06cc \u0637\u0628\u06cc\u0639\u06cc\u060c \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u067e\u0627\u0633\u062e\u200c\u062f\u0647\u06cc \u0628\u0627\u0642\u06cc \u0646\u0645\u06cc\u200c\u0645\u0627\u0646\u062f \u0648 \u0622\u0645\u0646\u0648\u0631\u0647 \u062b\u0627\u0646\u0648\u06cc\u0647 \u0627\u06cc\u062c\u0627\u062f \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062f\u0631 \u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u200c\u0647\u0627 \u067e\u0627\u06cc\u06cc\u0646 \u06cc\u0627 \u00ab\u0637\u0628\u06cc\u0639\u06cc\u0650 \u067e\u0627\u06cc\u06cc\u0646\u00bb \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0632\u0645\u06cc\u0646\u0647\u0654 \u0627\u0633\u062a\u0631\u0633/\u06a9\u0627\u0647\u0634 \u0648\u0632\u0646 \u06af\u0632\u0627\u0631\u0634 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0622\u062f\u0646\u0648\u0645 \u062a\u0631\u0634\u062d\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f \u0648 \u062f\u0631 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 FSH/LH \u0628\u0627\u0644\u0627\u0633\u062a \u06a9\u0647 \u0647\u06cc\u0686\u200c\u06a9\u062f\u0627\u0645 \u0628\u0627 \u0627\u06cc\u0646 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0637\u0628\u06cc\u0639\u06cc \u0648 \u0633\u0627\u0628\u0642\u0647\u0654 \u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u0646\u0627\u0633\u0628 \u0646\u062f\u0627\u0631\u0646\u062f.",
   "reasons": ["\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633\u06cc \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 \u06a9\u0627\u0647\u0634 \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646\u200c\u0647\u0627 \u06cc\u0627 \u0632\u0645\u06cc\u0646\u0647\u0654 \u0627\u0633\u062a\u0631\u0633/\u06a9\u0627\u0647\u0634 \u0648\u0632\u0646 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0646\u0647 \u0627\u06cc\u0646 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644.", "\u0622\u062f\u0646\u0648\u0645 \u062a\u0631\u0634\u062d\u200c\u06a9\u0646\u0646\u062f\u0647\u0654 \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u0628\u0627 \u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0622\u06cc\u062f \u06a9\u0647 \u0627\u06cc\u0646\u200c\u062c\u0627 \u0637\u0628\u06cc\u0639\u06cc \u0627\u0633\u062a.", "\u062f\u0631 \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 FSH \u0648 LH \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0631\u0648\u062f \u0646\u0647 \u0627\u06cc\u0646\u200c\u06a9\u0647 \u0637\u0628\u06cc\u0639\u06cc \u0628\u0645\u0627\u0646\u062f.", "\u06a9\u0648\u0631\u062a\u0627\u0698 \u0642\u0628\u0644\u06cc + \u0622\u0645\u0646\u0648\u0631\u0647 \u0628\u0627 \u0647\u0648\u0631\u0645\u0648\u0646\u200c\u0647\u0627\u06cc \u0637\u0628\u06cc\u0639\u06cc \u0627\u0644\u06af\u0648\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0622\u0634\u0631\u0645\u0646 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 9): {
   "topic": "psttTumor",
   "lead": "\u062a\u0648\u062f\u0647\u0654 \u067e\u064f\u0631\u0639\u0631\u0648\u0642 \u0631\u062d\u0645\u06cc \u0645\u0627\u0647\u200c\u0647\u0627 \u067e\u0633 \u0627\u0632 \u0633\u0642\u0637 \u0628\u0627 BHCG \u067e\u0627\u06cc\u06cc\u0646: \u062a\u0648\u0645\u0648\u0631 \u0627\u067e\u06cc\u062a\u0644\u06cc\u0648\u0626\u06cc\u062f \u0645\u062d\u0644 \u062c\u0641\u062a (PSTT) \u0631\u0627 \u062c\u062f\u06cc \u0628\u06af\u06cc\u0631.",
   "interpretation": "\u06a9\u0648\u0631\u06cc\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645\u0627 \u0648 \u0645\u0648\u0644 \u0645\u0647\u0627\u062c\u0645 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0628\u0627 BHCG \u0628\u0633\u06cc\u0627\u0631 \u0628\u0627\u0644\u0627 \u0647\u0645\u0631\u0627\u0647\u200c\u0627\u0646\u062f \u062f\u0631\u062d\u0627\u0644\u06cc\u200c\u06a9\u0647 PSTT \u0627\u0632 \u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0628\u06cc\u0646\u0627\u0628\u06cc\u0646\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a \u0645\u062d\u0644 \u0644\u0627\u0646\u0647\u200c\u06af\u0632\u06cc\u0646\u06cc \u062c\u0641\u062a \u0633\u0631\u0686\u0634\u0645\u0647 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u062a\u06cc\u062a\u0631 BHCG \u0622\u0646 \u0628\u0647\u200c\u0646\u0633\u0628\u062a \u062d\u062c\u0645 \u062a\u0648\u0645\u0648\u0631 \u067e\u0627\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0645\u0627\u0646\u062f\u061b \u0648\u0642\u062a\u06cc \u0645\u0627\u0647\u200c\u0647\u0627 \u067e\u0633 \u0627\u0632 \u06cc\u06a9 \u062d\u0627\u0645\u0644\u06af\u06cc (\u062d\u062a\u06cc \u0633\u0642\u0637) \u062a\u0648\u062f\u0647\u0654 \u0631\u062d\u0645\u06cc \u067e\u064f\u0631\u0639\u0631\u0648\u0642 \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0648 BHCG \u067e\u0627\u06cc\u06cc\u0646 (\u0645\u062b\u0644 \u06f2\u06f5) \u062f\u06cc\u062f\u0647 \u0634\u0648\u062f\u060c PSTT \u062f\u0631 \u0635\u062f\u0631 \u0642\u0631\u0627\u0631 \u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u062e\u0648\u062f \u0646\u06cc\u0632 \u0628\u0627\u0641\u062a \u0648\u0632\u06cc\u06a9\u0648\u0644\u0627\u0631 \u0628\u062f\u0648\u0646 \u062c\u0646\u06cc\u0646 \u0628\u0627 BHCG \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "reasons": ["\u06a9\u0648\u0631\u06cc\u0648\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645\u0627 \u0628\u0627 BHCG \u0628\u0647\u200c\u0634\u062f\u062a \u0628\u0627\u0644\u0627 \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a \u0646\u0647 \u06f2\u06f5 \u0648\u0627\u062d\u062f.", "\u0645\u0648\u0644 \u0645\u0647\u0627\u062c\u0645 \u0646\u06cc\u0632 \u0645\u0639\u0645\u0648\u0644\u0627\u064b BHCG \u0628\u0627\u0644\u0627 \u0648 \u0632\u0645\u06cc\u0646\u0647\u0654 \u0645\u0648\u0644 \u0627\u062e\u06cc\u0631 \u062f\u0627\u0631\u062f.", "BHCG \u067e\u0627\u06cc\u06cc\u0646 + \u062a\u0648\u062f\u0647\u0654 \u0631\u062d\u0645\u06cc \u067e\u064f\u0631\u0639\u0631\u0648\u0642 \u067e\u0633 \u0627\u0632 \u062f\u0648\u0631\u0647\u0654 \u0637\u0648\u0644\u0627\u0646\u06cc \u0627\u0632 \u062d\u0627\u0645\u0644\u06af\u06cc\u060c PSTT \u0631\u0627 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u0648\u0644 \u06a9\u0627\u0645\u0644 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0628\u0627 BHCG \u0628\u0627\u0644\u0627 \u0648 \u0638\u0627\u0647\u0631 \u062f\u0627\u0646\u0647\u200c\u0627\u0646\u06af\u0648\u0631\u06cc \u062f\u0631 \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0645\u06cc\u200c\u0622\u06cc\u062f."],
  },
  (28, 10): {
   "topic": "threatenedAbortion",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u06f9 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062c\u0646\u06cc\u0646 \u0632\u0646\u062f\u0647 \u0648 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0648 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0633\u062a\u0647\u0654 \u0633\u0631\u0648\u06cc\u06a9\u0633: \u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637 \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0645\u0624\u06cc\u062f.",
   "interpretation": "\u0647\u0645\u200c\u0632\u0645\u0627\u0646\u06cc \u0633\u0647 \u0646\u0634\u0627\u0646\u0647\u0654 \u00ab\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc/\u0644\u06a9\u0647\u200c\u0628\u06cc\u0646\u06cc \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0627\u0648\u0644\u00bb\u060c \u00ab\u062c\u0646\u06cc\u0646 \u0632\u0646\u062f\u0647 \u0628\u0627 \u0636\u0631\u0628\u0627\u0646 \u0642\u0644\u0628 \u0637\u0628\u06cc\u0639\u06cc\u00bb \u0648 \u00ab\u062f\u0647\u0627\u0646\u0647\u0654 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0633\u062a\u0647\u00bb \u062a\u0639\u0631\u06cc\u0641 \u0633\u0642\u0637 \u062a\u0647\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u0627\u0633\u062a\u061b \u062f\u0631 \u0627\u06cc\u0646 \u0648\u0636\u0639\u06cc\u062a \u062f\u062e\u0627\u0644\u062a (\u06a9\u0648\u0631\u062a\u0627\u0698\u060c \u0633\u0631\u06a9\u0644\u0627\u0698 \u06cc\u0627 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645) \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f \u0648 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0635\u062d\u06cc\u062d\u060c \u0622\u0631\u0627\u0645\u200c\u0633\u0627\u0632\u06cc\u060c \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0627\u0633\u062a. \u06a9\u0648\u0631\u062a\u0627\u0698 \u0628\u0631\u0627\u06cc \u0633\u0642\u0637 \u0642\u0637\u0639\u06cc/\u0646\u0627\u0642\u0635/\u0639\u0641\u0648\u0646\u06cc \u0627\u0633\u062a\u060c \u0633\u0631\u06a9\u0644\u0627\u0698 \u0628\u0631\u0627\u06cc \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0648 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0627\u0628\u0642\u0647\u0654 \u0628\u0627\u0644\u06cc\u0646\u06cc \u06a9\u0627\u0631\u0628\u0631\u062f\u06cc \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u062f\u0631 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0633\u0642\u0637 \u062a\u0647\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647 \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u062c\u0646\u06cc\u0646 \u0632\u0646\u062f\u0647 \u0648 \u062f\u0647\u0627\u0646\u0647\u0654 \u0628\u0633\u062a\u0647 \u062a\u0631\u06a9\u06cc\u0628 \u062a\u0647\u062f\u06cc\u062f \u0628\u0647 \u0633\u0642\u0637 \u0631\u0627 \u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0631\u06a9\u0644\u0627\u0698 \u0628\u0631\u0627\u06cc \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0627\u0633\u062a \u0646\u0647 \u0633\u0642\u0637 \u062a\u0647\u062f\u06cc\u062f\u06a9\u0646\u0646\u062f\u0647.", "\u06a9\u0648\u0631\u062a\u0627\u0698 \u0627\u0648\u0631\u0698\u0627\u0646\u0633\u06cc \u0641\u0642\u0637 \u062f\u0631 \u0633\u0642\u0637 \u0642\u0637\u0639\u06cc\u060c \u0646\u0627\u0642\u0635 \u06cc\u0627 \u0639\u0641\u0648\u0646\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a."],
  },
  (28, 11): {
   "topic": "posttermFetalCause",
   "lead": "\u06a9\u0645\u06a9\u0627\u0631\u06cc/\u0647\u0627\u06cc\u067e\u0648\u067e\u0644\u0627\u0632\u06cc \u0622\u062f\u0631\u0646\u0627\u0644 \u062c\u0646\u06cc\u0646\u06cc \u0627\u0632 \u0639\u0648\u0627\u0645\u0644\u06cc \u0627\u0633\u062a \u06a9\u0647 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u062a\u0631\u200c\u0634\u062f\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc (\u067e\u0633 \u0627\u0632 \u062a\u0631\u0645) \u0631\u0627 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f.",
   "interpretation": "\u062f\u0631 \u0641\u06cc\u0632\u06cc\u0648\u0644\u0648\u0698\u06cc \u0634\u0631\u0648\u0639 \u0632\u0627\u06cc\u0645\u0627\u0646\u060c \u0645\u062d\u0648\u0631 \u0647\u06cc\u067e\u0648\u062a\u0627\u0644\u0627\u0645\u0648\u0633-\u0647\u06cc\u067e\u0648\u0641\u06cc\u0632-\u0622\u062f\u0631\u0646\u0627\u0644 \u062c\u0646\u06cc\u0646 (\u0628\u0627 \u062a\u0648\u0644\u06cc\u062f DHEAS \u0648 \u06a9\u0648\u0631\u062a\u06cc\u0632\u0648\u0644) \u062f\u0631 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u062c\u0641\u062a \u0648 \u0622\u063a\u0627\u0632 \u0645\u0631\u0627\u062d\u0644 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0646\u0642\u0634 \u062f\u0627\u0631\u062f\u061b \u0646\u0642\u0635 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u062d\u0648\u0631 (\u0645\u062b\u0644 \u0647\u0627\u06cc\u067e\u0648\u067e\u0644\u0627\u0632\u06cc \u0622\u062f\u0631\u0646\u0627\u0644 \u06cc\u0627 \u0622\u0646\u0633\u0641\u0627\u0644\u06cc) \u0634\u0631\u0648\u0639 \u0628\u0647\u200c\u0645\u0648\u0642\u0639 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0631\u0627 \u0645\u062e\u062a\u0644 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062e\u0637\u0631 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f. \u0647\u06cc\u062f\u0631\u0648\u0633\u0641\u0627\u0644\u06cc \u0648 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u067e\u06cc\u0627\u0645\u062f\u0647\u0627\u06cc \u0631\u0634\u062f\u06cc \u0647\u0633\u062a\u0646\u062f \u0648 \u0633\u0646\u062f\u0631\u0645 \u062f\u06cc\u0633\u0645\u0627\u062a\u0648\u0631\u06cc\u062a\u06cc \u062e\u0648\u062f \u0646\u062a\u06cc\u062c\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0627\u0633\u062a \u0646\u0647 \u0639\u0627\u0645\u0644 \u0632\u0645\u0627\u0646\u200c\u0628\u0646\u062f\u06cc \u0622\u0646.",
   "reasons": ["\u0646\u0642\u0635 \u0645\u062d\u0648\u0631 \u0622\u062f\u0631\u0646\u0627\u0644 \u062c\u0646\u06cc\u0646\u06cc\u060c \u0633\u06cc\u06af\u0646\u0627\u0644 \u0637\u0628\u06cc\u0639\u06cc \u0622\u063a\u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0631\u0627 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0631\u0627 \u0628\u06cc\u0634\u200c\u062a\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0647\u06cc\u062f\u0631\u0648\u0633\u0641\u0627\u0644\u06cc \u0631\u0627\u0628\u0637\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645\u06cc \u0628\u0627 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0634\u062f\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u067e\u06cc\u0627\u0645\u062f \u0631\u0634\u062f \u0627\u0633\u062a \u0646\u0647 \u0639\u0644\u062a \u0632\u0645\u0627\u0646\u200c\u0628\u0646\u062f\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646.", "\u0633\u0646\u062f\u0631\u0645 \u062f\u06cc\u0633\u0645\u0627\u062a\u0648\u0631\u06cc\u062a\u06cc \u0646\u062a\u06cc\u062c\u0647\u0654 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u0633 \u0627\u0632 \u062a\u0631\u0645 \u0627\u0633\u062a \u0646\u0647 \u0639\u0644\u062a \u0622\u0646."],
  },
  (28, 12): {
   "topic": "cervicalCancerStageAdvanced",
   "lead": "\u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645 \u0633\u0646\u06af\u0641\u0631\u0634\u06cc \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0628\u0627 \u062f\u0631\u06af\u06cc\u0631\u06cc \u067e\u0627\u0631\u0627\u0645\u062a\u0631 \u06cc\u0639\u0646\u06cc \u0628\u06cc\u0645\u0627\u0631\u06cc \u062d\u062f\u0627\u0642\u0644 \u0648\u0627\u0631\u062f \u0645\u0631\u062d\u0644\u0647\u0654 \u06f2B \u0634\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f\u060c \u06a9\u0645\u0648\u0631\u0627\u062f\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc \u0647\u0645\u200c\u0632\u0645\u0627\u0646 (\u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0648 \u067e\u0631\u062a\u0648\u062f\u0631\u0645\u0627\u0646\u06cc) \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631 \u0633\u0631\u0637\u0627\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633\u060c \u062a\u0627 \u0631\u0633\u06cc\u062f\u0646 \u062a\u0648\u0645\u0648\u0631 \u0628\u0647 \u067e\u0627\u0631\u0627\u0645\u062a\u0631 \u06cc\u0627 \u062f\u06cc\u0648\u0627\u0631\u0647\u0654 \u0644\u06af\u0646 \u062c\u0631\u0627\u062d\u06cc \u0631\u0627\u062f\u06cc\u06a9\u0627\u0644 \u067e\u0627\u0633\u062e \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u0635\u0644\u06cc\u060c \u0631\u0627\u062f\u06cc\u0648\u062a\u0631\u0627\u067e\u06cc \u062e\u0627\u0631\u062c\u06cc+\u0628\u0631\u0627\u06a9\u06cc\u200c\u062a\u0631\u0627\u067e\u06cc \u0647\u0645\u0631\u0627\u0647 \u0628\u0627 \u0633\u06cc\u0633\u067e\u0644\u0627\u062a\u06cc\u0646 \u0647\u0645\u200c\u0632\u0645\u0627\u0646 (\u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0648 \u067e\u0631\u062a\u0648\u062f\u0631\u0645\u0627\u0646\u06cc) \u0627\u0633\u062a\u061b \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u067e\u0627\u0633\u062e \u06a9\u0627\u0645\u0644 \u0646\u06cc\u0633\u062a \u0648 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0633\u0627\u062f\u0647 \u062f\u0631 \u0647\u06cc\u0686 \u0645\u0631\u062d\u0644\u0647\u0654 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0628\u06cc\u0645\u0627\u0631\u06cc \u0641\u0639\u0627\u0644 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a \u0648 \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0631\u0627\u062f\u06cc\u06a9\u0627\u0644 \u0641\u0642\u0637 \u062f\u0631 \u0645\u0631\u0627\u062d\u0644 \u0627\u0648\u0644\u06cc\u0647\u0654 \u0628\u062f\u0648\u0646 \u062f\u0631\u06af\u06cc\u0631\u06cc \u067e\u0627\u0631\u0627\u0645\u062a\u0631 \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0627\u0631\u062f.",
   "reasons": ["\u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631\u0645\u0627\u0646 \u0627\u0635\u0644\u06cc \u0645\u0631\u062d\u0644\u0647\u0654 \u062f\u0631\u06af\u06cc\u0631 \u067e\u0627\u0631\u0627\u0645\u062a\u0631 \u0646\u06cc\u0633\u062a.", "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0633\u0627\u062f\u0647 \u062f\u0631 \u0628\u062f\u062e\u06cc\u0645\u06cc \u0641\u0639\u0627\u0644 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0631\u0627\u062f\u06cc\u06a9\u0627\u0644 \u0628\u0631\u0627\u06cc \u0645\u0631\u0627\u062d\u0644 \u0627\u0648\u0644\u06cc\u0647\u0654 \u0628\u062f\u0648\u0646 \u062f\u0631\u06af\u06cc\u0631\u06cc \u067e\u0627\u0631\u0627\u0645\u062a\u0631 \u0627\u0633\u062a.", "\u062f\u0631\u06af\u06cc\u0631\u06cc \u067e\u0627\u0631\u0627\u0645\u062a\u0631 \u06cc\u0639\u0646\u06cc \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0648 \u067e\u0631\u062a\u0648\u062f\u0631\u0645\u0627\u0646\u06cc \u0647\u0645\u200c\u0632\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 13): {
   "topic": "hysteroscopyIndication",
   "lead": "\u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u0628\u0627 \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0627\u0644\u0627 \u0648 \u0646\u062a\u06cc\u062c\u0647\u0654 \u063a\u06cc\u0631\u062a\u0634\u062e\u06cc\u0635\u06cc \u0628\u06cc\u0648\u067e\u0633\u06cc \u06a9\u0648\u0631: \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u06af\u06cc\u0631\u06cc \u0647\u062f\u0627\u06cc\u062a\u200c\u0634\u062f\u0647.",
   "interpretation": "\u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u06a9\u0648\u0631 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0636\u0627\u06cc\u0639\u0627\u062a \u06a9\u0627\u0646\u0648\u0646\u06cc (\u067e\u0648\u0644\u06cc\u067e/\u0641\u06cc\u0628\u0631\u0648\u0645 \u0632\u06cc\u0631\u0645\u062e\u0627\u0637\u06cc/\u0636\u0627\u06cc\u0639\u0627\u062a \u0645\u062d\u062f\u0648\u062f) \u0631\u0627 \u062c\u0627 \u0628\u06cc\u0646\u062f\u0627\u0632\u062f \u0648 \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u063a\u06cc\u0631\u0637\u0628\u06cc\u0639\u06cc \u0645\u0642\u0627\u0648\u0645 \u06cc\u0627 \u0636\u062e\u0627\u0645\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u0628\u0627\u0644\u0627\u060c \u06af\u0632\u0627\u0631\u0634 \u00ab\u063a\u06cc\u0631\u062a\u0634\u062e\u06cc\u0635\u06cc\u00bb \u0628\u0647 \u0645\u0639\u0646\u0627\u06cc \u067e\u0627\u06cc\u0627\u0646 \u06a9\u0627\u0631 \u0646\u06cc\u0633\u062a\u061b \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0645\u06a9\u0627\u0646 \u062f\u06cc\u062f \u0645\u0633\u062a\u0642\u06cc\u0645 \u062d\u0641\u0631\u0647\u0654 \u0631\u062d\u0645 \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u06af\u06cc\u0631\u06cc \u0647\u062f\u0627\u06cc\u062a\u200c\u0634\u062f\u0647 \u0627\u0632 \u0636\u0627\u06cc\u0639\u0647 \u0631\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f. \u062a\u062c\u0648\u06cc\u0632 \u062a\u062c\u0631\u0628\u06cc \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u06cc\u0627 \u0645\u06cc\u0631\u0646\u0627 \u067e\u06cc\u0634 \u0627\u0632 \u0631\u0648\u0634\u0646\u200c\u0634\u062f\u0646 \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0632\u06cc\u0631\u0633\u0627\u062e\u062a \u062a\u0634\u062e\u06cc\u0635\u06cc \u0631\u0627 \u067e\u0646\u0647\u0627\u0646 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u062a\u06a9\u0631\u0627\u0631 \u0647\u0645\u0627\u0646 \u0631\u0648\u0634 \u06a9\u0648\u0631 \u0627\u062d\u062a\u0645\u0627\u0644 \u0628\u0627\u0632\u062a\u0648\u0644\u06cc\u062f \u062e\u0637\u0627 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u062f.",
   "reasons": ["\u062a\u06a9\u0631\u0627\u0631 \u0628\u06cc\u0648\u067e\u0633\u06cc \u06a9\u0648\u0631 \u0627\u062d\u062a\u0645\u0627\u0644\u0627\u064b \u0647\u0645\u0627\u0646 \u0646\u0645\u0648\u0646\u0647\u0654 \u0646\u0627\u06a9\u0627\u0641\u06cc \u0631\u0627 \u0628\u0627\u0632\u062a\u0648\u0644\u06cc\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0627 \u0646\u0645\u0648\u0646\u0647\u200c\u06af\u06cc\u0631\u06cc \u0647\u062f\u0627\u06cc\u062a\u200c\u0634\u062f\u0647 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u067e\u0633 \u0627\u0632 \u0628\u06cc\u0648\u067e\u0633\u06cc \u063a\u06cc\u0631\u062a\u0634\u062e\u06cc\u0635\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u0635\u0631\u0641 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0628\u062f\u0648\u0646 \u0631\u0648\u0634\u0646\u200c\u0634\u062f\u0646 \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0628\u0631\u062c\u0633\u062a\u0647 \u0646\u06cc\u0633\u062a.", "\u06af\u0630\u0627\u0634\u062a\u0646 IUD \u0645\u06cc\u0631\u0646\u0627 \u0642\u0628\u0644 \u0627\u0632 \u0631\u0648\u0634\u0646\u200c\u0634\u062f\u0646 \u062a\u0634\u062e\u06cc\u0635 \u062f\u0631\u0633\u062a \u0646\u06cc\u0633\u062a."],
  },
  (28, 14): {
   "topic": "sfhAboveDatesExcept",
   "lead": "\u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0628\u0647\u200c\u0645\u0631\u0627\u062a\u0628 \u0628\u06cc\u0634\u200c\u0627\u0632 \u0633\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645: \u0627\u0634\u062a\u0628\u0627\u0647 \u062f\u0631 \u062a\u0627\u0631\u06cc\u062e\u060c \u0641\u06cc\u0628\u0631\u0648\u0645 \u0631\u062d\u0645\u06cc \u0648 \u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0645\u0637\u0631\u062d\u200c\u0627\u0646\u062f\u061b \u0645\u0631\u06af \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0639\u0644\u062a \u0628\u0632\u0631\u06af\u200c\u0634\u062f\u0646 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0627\u0641\u0632\u0627\u06cc\u0634 \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0641\u0631\u0627\u062a\u0631 \u0627\u0632 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0646\u0627\u0634\u06cc \u0627\u0632 \u062e\u0637\u0627 \u062f\u0631 \u0628\u0632\u0631\u06af\u06cc \u0632\u0645\u0627\u0646\u06cc (\u06cc\u0639\u0646\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u06cc\u0634\u0631\u0641\u062a\u0647\u200c\u062a\u0631)\u060c \u062a\u0648\u062f\u0647\u200c\u0647\u0627\u06cc \u0631\u062d\u0645\u06cc \u0645\u062b\u0644 \u0641\u06cc\u0628\u0631\u0648\u0645\u060c \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 (\u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633) \u06cc\u0627 \u0645\u0627\u06a9\u0631\u0648\u0632\u0648\u0645\u06cc \u0628\u0627\u0634\u062f\u061b \u062f\u0631 \u0645\u0631\u06af \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u062c\u0646\u06cc\u0646 (IUFD) \u0628\u0627 \u0642\u0631\u0627\u0631\u06af\u06cc\u0631\u06cc \u0645\u062c\u062f\u062f \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0648 \u0627\u06cc\u0633\u062a \u0631\u0634\u062f\u060c \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u06a9\u0645\u062a\u0631 \u0627\u0632 \u0633\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc \u0645\u06cc\u200c\u0645\u0627\u0646\u062f \u0646\u0647 \u0628\u06cc\u0634\u200c\u062a\u0631\u060c \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 IUFD \u0627\u0633\u062a\u062b\u0646\u0627\u0633\u062a.",
   "reasons": ["\u0635\u062d\u06cc\u062d\u200c\u0646\u0628\u0648\u062f\u0646 \u0633\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc \u0627\u0632 \u0634\u0627\u06cc\u0639\u200c\u062a\u0631\u06cc\u0646 \u0639\u0644\u0644 \u0628\u0632\u0631\u06af \u0628\u0647 \u0646\u0638\u0631 \u0631\u0633\u06cc\u062f\u0646 \u0631\u062d\u0645 \u0627\u0633\u062a.", "\u0641\u06cc\u0628\u0631\u0648\u0645\u200c\u0647\u0627\u06cc \u0631\u062d\u0645\u06cc \u0631\u062d\u0645 \u0631\u0627 \u0628\u0632\u0631\u06af\u200c\u062a\u0631 \u0627\u0632 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u0634\u0627\u0646 \u0645\u06cc\u200c\u062f\u0647\u0646\u062f.", "IUFD \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u0627\u0631\u062a\u0641\u0627\u0639 \u0631\u062d\u0645 \u0631\u0627 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u0633\u0646 \u062d\u0627\u0645\u0644\u06af\u06cc \u0645\u06cc\u200c\u06a9\u0646\u062f \u0646\u0647 \u0628\u06cc\u0634\u062a\u0631\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0644\u06cc\u200c\u0647\u06cc\u062f\u0631\u0627\u0645\u0646\u06cc\u0648\u0633 \u0628\u0627 \u0645\u0627\u06cc\u0639 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0632\u06cc\u0627\u062f \u0631\u062d\u0645 \u0631\u0627 \u0628\u0632\u0631\u06af\u200c\u062a\u0631 \u0646\u0634\u0627\u0646 \u0645\u06cc\u200c\u062f\u0647\u062f."],
  },
  (28, 15): {
   "topic": "lsilUnsatisfactoryEcc",
   "lead": "\u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 LSIL \u0628\u0627 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0646\u0627\u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 (\u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 \u0646\u0628\u0648\u062f\u0646): \u06a9\u0648\u0631\u062a\u0627\u0698 \u0622\u0646\u062f\u0648\u0633\u0631\u0648\u06cc\u06a9\u0633 (ECC) \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u06a9\u0627\u0646\u0627\u0644 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.",
   "interpretation": "\u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 \u0632\u0645\u0627\u0646\u06cc \u0627\u0633\u062a \u06a9\u0647 \u062a\u0645\u0627\u0645 \u0646\u0627\u062d\u06cc\u0647\u0654 \u062a\u0628\u062f\u06cc\u0644 \u062f\u06cc\u062f\u0647 \u0634\u0648\u062f\u061b \u0648\u0642\u062a\u06cc \u0628\u0647 \u062f\u0644\u06cc\u0644 \u0645\u0647\u0627\u062c\u0631\u062a \u0645\u062a\u0642\u0627\u0628\u0644 \u0628\u0647 \u0633\u0645\u062a \u06a9\u0627\u0646\u0627\u0644 \u06cc\u0627 \u0639\u0644\u062a \u062f\u06cc\u06af\u0631 \u0627\u06cc\u0646 \u0646\u0627\u062d\u06cc\u0647 \u06a9\u0627\u0645\u0644 \u062f\u06cc\u062f\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u062f\u0631 \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 LSIL (\u0648 \u0628\u0627\u0644\u0627\u062a\u0631) \u062e\u0637\u0631 \u0648\u062c\u0648\u062f \u0636\u0627\u06cc\u0639\u0647 \u062f\u0631 \u06a9\u0627\u0646\u0627\u0644 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0647\u0633\u062a \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u0627\u0632 \u06a9\u0627\u0646\u0627\u0644 (\u06a9\u0648\u0631\u062a\u0627\u0698 \u0622\u0646\u062f\u0648\u0633\u0631\u0648\u06cc\u06a9\u0633) \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0628\u0639\u062f\u06cc \u0627\u0633\u062a \u062a\u0627 \u0636\u0627\u06cc\u0639\u0647\u0654 \u062f\u0627\u062e\u0644 \u06a9\u0627\u0646\u0627\u0644\u06cc \u0631\u062f \u0646\u0634\u0648\u062f\u061b \u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc LSIL \u0628\u06cc\u0634 \u0627\u0632 \u062d\u062f \u0644\u0627\u0632\u0645 \u0627\u0633\u062a\u060c \u062a\u06a9\u0631\u0627\u0631 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u0686\u0646\u06cc\u0646 \u0635\u0648\u0631\u062a\u06cc \u062a\u0635\u0645\u06cc\u0645 \u0631\u0627 \u0628\u0647 \u062a\u0639\u0648\u06cc\u0642 \u0645\u06cc\u200c\u0627\u0646\u062f\u0627\u0632\u062f \u0648 \u062a\u0633\u062a HPV \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0647\u06cc\u0633\u062a\u0631\u06a9\u062a\u0648\u0645\u06cc \u0628\u0631\u0627\u06cc LSIL \u0628\u0627 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0646\u0627\u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a.", "\u062a\u0633\u062a HPV \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647\u0654 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0646\u0627\u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 \u067e\u0627\u0633\u062e \u062a\u06a9\u0645\u06cc\u0644\u06cc \u0646\u06cc\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u06f2 \u0645\u0627\u0647 \u0628\u0639\u062f \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u062a\u0623\u062e\u06cc\u0631 \u062f\u0631 \u062a\u0634\u062e\u06cc\u0635 \u0636\u0627\u06cc\u0639\u0647\u0654 \u06a9\u0627\u0646\u0627\u0644 \u0627\u0633\u062a.", "ECC \u062f\u0631 \u06a9\u0648\u0644\u067e\u0648\u0633\u06a9\u0648\u067e\u06cc \u0646\u0627\u0631\u0636\u0627\u06cc\u062a\u200c\u0628\u062e\u0634 \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u06a9\u0627\u0646\u0627\u0644 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 16): {
   "topic": "endoHyperplasiaRisk",
   "lead": "\u0645\u0647\u0645\u200c\u062a\u0631\u06cc\u0646 \u0631\u06cc\u0633\u06a9 \u0647\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0647\u0631\u0633\u062a\u060c \u0645\u0635\u0631\u0641 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062f\u0631 \u06cc\u0627\u0626\u0633\u06af\u06cc \u0627\u0633\u062a (\u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u0645\u0642\u0627\u0628\u0644).",
   "interpretation": "\u0647\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0639\u0645\u062f\u062a\u0627\u064b \u0646\u0627\u0634\u06cc \u0627\u0632 \u062a\u062d\u0631\u06cc\u06a9 \u0645\u0632\u0645\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0627 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0627\u0633\u062a\u061b \u0645\u0635\u0631\u0641 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u0632\u0646\u0627\u0646 \u06cc\u0627\u0626\u0633\u0647\u0654 \u062f\u0627\u0631\u0627\u06cc \u0631\u062d\u0645 \u0642\u0648\u06cc\u200c\u062a\u0631\u06cc\u0646 \u0648 \u0645\u0633\u062a\u0642\u06cc\u0645\u200c\u062a\u0631\u06cc\u0646 \u0645\u0646\u0634\u0623 \u0627\u06cc\u0646 \u062a\u062d\u0631\u06cc\u06a9 \u0627\u0633\u062a \u0648 \u062e\u0637\u0631 \u0631\u0627 \u0686\u0646\u062f \u0628\u0631\u0627\u0628\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f. \u0686\u0627\u0642\u06cc \u0627\u0632 \u0631\u0627\u0647 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u062f\u0631\u0648\u0646\u200c\u0632\u0627\u062f (\u062a\u0628\u062f\u06cc\u0644 \u0622\u0646\u062f\u0631\u0648\u0633\u062a\u0646\u062f\u06cc\u0648\u0646 \u0628\u0647 \u0627\u0633\u062a\u0631\u0648\u0646 \u062f\u0631 \u0686\u0631\u0628\u06cc) \u0627\u062b\u0631 \u063a\u06cc\u0631\u0645\u0633\u062a\u0642\u06cc\u0645\u200c\u062a\u0631 \u062f\u0627\u0631\u062f\u060c \u062a\u0627\u0645\u0648\u06a9\u0633\u06cc\u0641\u0646 \u0627\u062b\u0631 \u0622\u06af\u0648\u0646\u06cc\u0633\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u062f\u0627\u0631\u062f \u0648\u0644\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0642\u0627\u06cc\u0633\u0647 \u0648\u0632\u0646 \u06a9\u0645\u062a\u0631\u06cc \u062f\u0627\u0631\u062f \u0648 \u06cc\u0627\u0626\u0633\u06af\u06cc \u062f\u06cc\u0631\u0631\u0633 \u0628\u0627 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0634\u062f\u0646 \u062a\u062d\u0631\u06cc\u06a9 \u0627\u0633\u062a\u0631\u0648\u0698\u0646\u06cc \u0627\u062b\u0631 \u0645\u062a\u0648\u0633\u0637\u06cc \u062f\u0627\u0631\u062f.",
   "reasons": ["\u0645\u0635\u0631\u0641 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u0645\u0642\u0627\u0628\u0644 \u062f\u0631 \u06cc\u0627\u0626\u0633\u06af\u06cc \u0628\u0627\u0644\u0627\u062a\u0631\u06cc\u0646 \u0631\u06cc\u0633\u06a9 \u0647\u06cc\u067e\u0631\u067e\u0644\u0627\u0632\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u062f\u0627\u0631\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0686\u0627\u0642\u06cc \u0627\u0632 \u0631\u0627\u0647 \u0645\u062a\u0627\u0628\u0648\u0644\u06cc\u0633\u0645 \u0627\u0633\u062a\u0631\u0648\u0698\u0646\u06cc \u0627\u062b\u0631 \u063a\u06cc\u0631\u0645\u0633\u062a\u0642\u06cc\u0645\u200c\u062a\u0631 \u062f\u0627\u0631\u062f.", "\u062a\u0627\u0645\u0648\u06a9\u0633\u06cc\u0641\u0646 \u0627\u062b\u0631 \u0622\u06af\u0648\u0646\u06cc\u0633\u062a\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc \u0645\u062d\u062f\u0648\u062f\u200c\u062a\u0631\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0642\u0627\u06cc\u0633\u0647 \u062f\u0627\u0631\u062f.", "\u06cc\u0627\u0626\u0633\u06af\u06cc \u062f\u06cc\u0631\u0631\u0633 \u062a\u062d\u0631\u06cc\u06a9 \u0627\u0633\u062a\u0631\u0648\u0698\u0646\u06cc \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u062a\u0631\u06cc \u0645\u06cc\u200c\u0633\u0627\u0632\u062f \u0648\u0644\u06cc \u0648\u0632\u0646 \u0622\u0646 \u06a9\u0645\u200c\u062a\u0631 \u0627\u0632 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0628\u062f\u0648\u0646 \u0645\u0642\u0627\u0628\u0644 \u0627\u0633\u062a."],
  },
  (28, 17): {
   "topic": "salpingectomyBenefit",
   "lead": "\u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u0644\u0648\u0644\u0647\u200c\u0647\u0627\u06cc \u0631\u062d\u0645\u06cc (\u0633\u0627\u0644\u067e\u0646\u0698\u06a9\u062a\u0648\u0645\u06cc) \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u062a\u062e\u0645\u062f\u0627\u0646/\u0644\u0648\u0644\u0647\u0654 \u0641\u0627\u0644\u0648\u067e \u0631\u0627 \u06a9\u0645 \u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u0646\u0647 \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u060c \u0633\u0631\u0648\u06cc\u06a9\u0633 \u06cc\u0627 \u067e\u0633\u062a\u0627\u0646.",
   "interpretation": "\u0628\u062e\u0634 \u0642\u0627\u0628\u0644\u200c\u062a\u0648\u062c\u0647\u06cc \u0627\u0632 \u06a9\u0627\u0631\u0633\u06cc\u0646\u0648\u0645\u200c\u0647\u0627\u06cc \u0633\u0631\u0648\u0632 \u062f\u0631\u062c\u0647\u0654 \u0628\u0627\u0644\u0627\u06cc \u00ab\u062a\u062e\u0645\u062f\u0627\u0646\u00bb \u062f\u0631 \u0648\u0627\u0642\u0639 \u0627\u0632 \u0645\u062e\u0627\u0637 \u0627\u0646\u062a\u0647\u0627\u06cc \u0644\u0648\u0644\u0647\u0654 \u0641\u0627\u0644\u0648\u067e (\u0644\u0648\u0644\u0647\u0654 \u0641\u0627\u0644\u0648\u067e) \u0633\u0631\u0686\u0634\u0645\u0647 \u0645\u06cc\u200c\u06af\u06cc\u0631\u0646\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u0633\u0627\u0644\u067e\u0646\u0698\u06a9\u062a\u0648\u0645\u06cc (\u0628\u0647\u200c\u062e\u0635\u0648\u0635 \u0628\u0647\u200c\u0645\u0646\u0632\u0644\u0654 \u067e\u06cc\u0634\u06af\u06cc\u0631\u06cc \u0641\u0631\u0635\u062a\u200c\u0637\u0644\u0628 \u0647\u0646\u06af\u0627\u0645 \u062c\u0631\u0627\u062d\u06cc \u0644\u06af\u0646 \u062f\u06cc\u06af\u0631) \u062e\u0637\u0631 \u0627\u06cc\u0646 \u0633\u0631\u0637\u0627\u0646\u200c\u0647\u0627 \u0631\u0627 \u0628\u0647\u200c\u0637\u0648\u0631 \u0645\u0639\u0646\u0627\u062f\u0627\u0631 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f. \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0639\u0645\u062f\u062a\u0627\u064b \u0627\u0633\u062a\u0631\u0648\u0698\u0646/\u0628\u0627\u0641\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0645\u0631\u062a\u0628\u0637 \u0627\u0633\u062a\u060c \u0633\u0631\u0637\u0627\u0646 \u0633\u0631\u0648\u06cc\u06a9\u0633 HPV-\u0648\u0627\u0628\u0633\u062a\u0647 \u0627\u0633\u062a \u0648 \u0633\u0631\u0637\u0627\u0646 \u067e\u0633\u062a\u0627\u0646 \u0628\u0627 \u0628\u0631\u062f\u0627\u0634\u062a\u0646 \u0644\u0648\u0644\u0647 \u062a\u0639\u06cc\u06cc\u0646 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u06a9\u0627\u0646\u0633\u0631 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0627 \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u0648 \u0628\u0627\u0641\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u062f\u0631 \u0627\u0631\u062a\u0628\u0627\u0637 \u0627\u0633\u062a \u0648 \u0628\u0627 \u0633\u0627\u0644\u067e\u0646\u0698\u06a9\u062a\u0648\u0645\u06cc \u06a9\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0633\u0627\u0644\u067e\u0646\u0698\u06a9\u062a\u0648\u0645\u06cc \u0628\u0627 \u06a9\u0627\u0647\u0634 \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u062a\u062e\u0645\u062f\u0627\u0646/\u0644\u0648\u0644\u0647\u0654 \u0641\u0627\u0644\u0648\u067e \u0647\u0645\u0631\u0627\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0627\u0646\u0633\u0631 \u0633\u0631\u0648\u06cc\u06a9\u0633 \u0646\u0627\u0634\u06cc \u0627\u0632 HPV \u0627\u0633\u062a \u0648 \u0633\u0627\u0644\u067e\u0646\u0698\u06a9\u062a\u0648\u0645\u06cc \u062f\u0631 \u0622\u0646 \u0627\u062b\u0631 \u0646\u062f\u0627\u0631\u062f.", "\u0633\u0627\u0644\u067e\u0646\u0698\u06a9\u062a\u0648\u0645\u06cc \u062a\u0623\u062b\u06cc\u0631\u06cc \u0628\u0631 \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u067e\u0633\u062a\u0627\u0646 \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 18): {
   "topic": "recurrentVvc",
   "lead": "\u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u06cc\u06cc \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647 (\u2265\u06f4 \u062d\u0645\u0644\u0647 \u062f\u0631 \u0633\u0627\u0644): \u067e\u0633 \u0627\u0632 \u0641\u0627\u0632 \u0627\u0644\u0642\u0627\u060c \u0633\u0631\u06a9\u0648\u0628 \u0646\u06af\u0647\u200c\u062f\u0627\u0631\u0646\u062f\u0647\u0654 \u0641\u0644\u0648\u06a9\u0648\u0646\u0627\u0632\u0648\u0644 \u06f1\u06f5\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u0647\u0641\u062a\u06af\u06cc \u0628\u0647\u200c\u0645\u062f\u062a \u06f6 \u0645\u0627\u0647.",
   "interpretation": "\u0648\u0642\u0648\u0639 \u062f\u0633\u062a\u200c\u06a9\u0645 \u0686\u0647\u0627\u0631 \u062d\u0645\u0644\u0647\u0654 \u0645\u0624\u06cc\u062f VVC \u062f\u0631 \u06cc\u06a9 \u0633\u0627\u0644 \u00ab\u0648\u0627\u0698\u06cc\u0646\u06cc\u062a \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u06cc\u06cc \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647\u00bb \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f \u0648 \u062f\u0631\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0622\u0646 \u062f\u0648 \u0645\u0631\u062d\u0644\u0647 \u062f\u0627\u0631\u062f: \u0627\u0628\u062a\u062f\u0627 \u062f\u0631\u0645\u0627\u0646 \u0627\u0644\u0642\u0627 (\u0645\u062b\u0644\u0627\u064b \u062f\u0648\u0631\u0647\u0654 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u062a\u0631 \u0636\u062f\u0642\u0627\u0631\u0686 \u0645\u0648\u0636\u0639\u06cc \u06cc\u0627 \u062e\u0648\u0631\u0627\u06a9\u06cc) \u0648 \u0633\u067e\u0633 \u062f\u0631\u0645\u0627\u0646 \u0646\u06af\u0647\u200c\u062f\u0627\u0631\u0646\u062f\u0647\u0654 \u0633\u0631\u06a9\u0648\u0628\u06cc \u0628\u0627 \u0641\u0644\u0648\u06a9\u0648\u0646\u0627\u0632\u0648\u0644 \u06f1\u06f5\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062e\u0648\u0631\u0627\u06a9\u06cc \u06cc\u06a9\u200c\u0628\u0627\u0631 \u062f\u0631 \u0647\u0641\u062a\u0647 \u0628\u0631\u0627\u06cc \u0634\u0634 \u0645\u0627\u0647 \u062a\u0627 \u062d\u062f\u0627\u06a9\u062b\u0631 \u06a9\u0627\u0647\u0634 \u0639\u0648\u062f \u062d\u0627\u0635\u0644 \u0634\u0648\u062f\u061b \u062f\u0648\u0631\u0647\u200c\u0647\u0627\u06cc \u06a9\u0648\u062a\u0627\u0647 \u0645\u0648\u0636\u0639\u06cc \u0633\u0647\u200c\u0631\u0648\u0632\u0647 \u06cc\u0627 \u062f\u0631\u0645\u0627\u0646 \u0634\u0631\u06cc\u06a9 \u062c\u0646\u0633\u06cc \u062f\u0631 \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647\u0654 \u0632\u0646\u0627\u0646 \u067e\u0627\u0633\u062e \u06a9\u0627\u0645\u0644 \u0648 \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0627\u06cc\u0645\u06cc\u062f\u0627\u0632\u0648\u0644 \u0645\u0648\u0636\u0639\u06cc \u0633\u0647\u200c\u0631\u0648\u0632\u0647 \u0628\u0631\u0627\u06cc VVC \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647 \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a.", "\u0641\u0644\u0648\u06a9\u0648\u0646\u0627\u0632\u0648\u0644 \u06f1\u06f5\u06f0 \u0647\u0641\u062a\u06af\u06cc \u0628\u0647\u200c\u0645\u062f\u062a \u06f6 \u0645\u0627\u0647 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0633\u0631\u06a9\u0648\u0628 \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0644\u0648\u062a\u0631\u06cc\u0645\u0627\u0632\u0648\u0644 \u0645\u0648\u0636\u0639\u06cc \u0633\u0647\u200c\u0631\u0648\u0632\u0647 \u0641\u0627\u0632 \u0646\u06af\u0647\u200c\u062f\u0627\u0631\u0646\u062f\u0647 \u0646\u06cc\u0633\u062a.", "\u062f\u0631\u0645\u0627\u0646 \u0634\u0631\u06cc\u06a9 \u062c\u0646\u0633\u06cc \u062f\u0631 \u06a9\u0627\u0646\u062f\u06cc\u062f\u06cc\u0627\u0632 \u0639\u0648\u062f\u06a9\u0646\u0646\u062f\u0647\u0654 \u0632\u0646\u0627\u0646 \u0646\u0642\u0634 \u0627\u062b\u0628\u0627\u062a\u200c\u0634\u062f\u0647 \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 19): {
   "topic": "bvAsymptomaticPap",
   "lead": "\u06af\u0632\u0627\u0631\u0634 \u0648\u0627\u0698\u06cc\u0646\u0648\u0632 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0627\u0644 \u0631\u0648\u06cc \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u062f\u0631 \u0632\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a: \u0645\u0639\u0645\u0648\u0644\u0627\u064b \u062f\u0631\u0645\u0627\u0646 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a \u0648 \u0627\u0637\u0645\u06cc\u0646\u0627\u0646\u200c\u0628\u062e\u0634 \u06a9\u0627\u0641\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u062f\u0631\u0645\u0627\u0646 BV \u0641\u0642\u0637 \u062f\u0631 \u0632\u0646\u0627\u0646 \u0639\u0644\u0627\u0645\u062a\u200c\u062f\u0627\u0631 (\u062a\u0631\u0634\u062d \u0628\u062f\u0628\u0648/\u062a\u062d\u0631\u06cc\u06a9 \u0648\u0644\u0648\u0648\u0627\u0698\u06cc\u0646) \u0648 \u0628\u0631 \u0627\u0633\u0627\u0633 \u0645\u0639\u06cc\u0627\u0631\u0647\u0627\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0646\u0647 \u0635\u0631\u0641\u0627\u064b \u0628\u0631 \u0627\u0633\u0627\u0633 \u0646\u062a\u06cc\u062c\u0647\u0654 \u0633\u06cc\u062a\u0648\u0644\u0648\u0698\u06cc \u0631\u0646\u06af\u200c\u0622\u0645\u06cc\u0632\u06cc\u200c\u0634\u062f\u0647 \u0628\u0627 \u00ab\u0633\u0644\u0648\u0644\u200c\u0647\u0627\u06cc \u0633\u0631\u0646\u062e\u00bb\u061b \u0645\u0641\u0647\u0648\u0645 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u067e\u0627\u067e\u200c\u0627\u0633\u0645\u06cc\u0631 \u0628\u0631\u0627\u06cc \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0633\u0631\u0637\u0627\u0646 \u0627\u0633\u062a \u0648 \u062a\u0634\u062e\u06cc\u0635 \u0628\u0627\u0644\u06cc\u0646\u06cc BV \u0631\u0627 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f. \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0632\u0646 \u0628\u062f\u0648\u0646 \u0634\u06a9\u0627\u06cc\u062a\u060c \u06cc\u0627\u0641\u062a\u0646 \u06af\u0632\u0627\u0631\u0634 BV \u062f\u0631 \u0633\u06cc\u062a\u0648\u0644\u0648\u0698\u06cc \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u0646\u06cc\u0627\u0632 \u0628\u0647 \u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u06cc\u0627 \u0628\u0631\u0631\u0633\u06cc\u200c\u0647\u0627\u06cc \u062a\u06a9\u0645\u06cc\u0644\u06cc (pH \u0648 \u0648\u062a\u200c\u0645\u0648\u0646\u062a) \u0646\u062f\u0627\u0631\u062f \u0648 \u0631\u0648\u06cc\u06a9\u0631\u062f \u0627\u0648\u0644\u06cc\u0647 \u0627\u0637\u0645\u06cc\u0646\u0627\u0646\u200c\u0628\u062e\u0634 \u0648 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc\u06cc \u0627\u0633\u062a.",
   "reasons": ["\u0628\u0631\u0631\u0633\u06cc pH \u062f\u0631 \u0641\u0642\u062f\u0627\u0646 \u0639\u0644\u0627\u06cc\u0645 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0644\u0632\u0648\u0645\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0648\u062a\u200c\u0645\u0648\u0646\u062a \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u0627\u06cc\u0645 \u062a\u0635\u0645\u06cc\u0645 \u0631\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0646\u0645\u06cc\u200c\u062f\u0647\u062f.", "\u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u062f\u0631 \u0632\u0646 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u0645\u062a \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0627\u0637\u0645\u06cc\u0646\u0627\u0646\u200c\u0628\u062e\u0634 \u0648 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc\u06cc \u0628\u0631\u0627\u06cc \u0645\u0631\u0627\u062c\u0639\u0647 \u062f\u0631 \u0635\u0648\u0631\u062a \u0639\u0644\u0627\u0626\u0645 \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d."],
  },
  (28, 20): {
   "topic": "gbsProphylaxisExcept",
   "lead": "\u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646\u06cc GBS \u0628\u0631\u0627\u06cc: \u0648\u0636\u0639\u06cc\u062a \u0646\u0627\u0645\u0634\u062e\u0635 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc GBS\u060c \u0646\u0648\u0632\u0627\u062f \u0642\u0628\u0644\u06cc \u0645\u0628\u062a\u0644\u0627\u060c \u062a\u0628 \u0645\u0627\u062f\u0631 \u06cc\u0627 \u0632\u0627\u06cc\u0645\u0627\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u062a\u0631\u0645 \u06cc\u0627 \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647>\u06f1\u06f8 \u0633\u0627\u0639\u062a \u06cc\u0627 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc GBS \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u061b \u00ab\u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0628\u0644\u06cc\u00bb \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a.",
   "interpretation": "\u0628\u0631\u0646\u0627\u0645\u0647\u0654 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0648 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc GBS \u062f\u0648\u0631\u0627\u0646 \u0632\u0627\u06cc\u0645\u0627\u0646\u06cc \u0628\u0631 \u0627\u0633\u0627\u0633 \u06a9\u0634\u062a \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0639\u0644\u06cc (\u06f3\u06f5-\u06f3\u06f7 \u0647\u0641\u062a\u0647)\u060c \u0633\u0627\u0628\u0642\u0647\u0654 \u0646\u0648\u0632\u0627\u062f \u0642\u0628\u0644\u06cc \u0645\u0628\u062a\u0644\u0627\u060c \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc GBS \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0639\u0644\u06cc \u0648 \u0634\u0631\u0627\u06cc\u0637 \u062f\u0627\u062e\u0644 \u0632\u0627\u06cc\u0645\u0627\u0646\u06cc (\u0632\u0627\u06cc\u0645\u0627\u0646 \u067e\u06cc\u0634 \u0627\u0632 \u06f3\u06f7 \u0647\u0641\u062a\u0647\u060c \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u062a\u0631 \u0627\u0632 \u06f1\u06f8 \u0633\u0627\u0639\u062a\u060c \u062a\u0628 \u062f\u0627\u062e\u0644 \u0632\u0627\u06cc\u0645\u0627\u0646\u06cc) \u0627\u0633\u062a\u061b \u0635\u0631\u0641 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc GBS \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0628\u0644\u06cc \u0628\u062f\u0648\u0646 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0641\u0639\u0644\u06cc \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0642\u0637\u0639\u06cc \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u0646\u06cc\u0633\u062a \u0648 \u06a9\u0644\u06cc\u062f \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u0647\u0645 \u0647\u0645\u06cc\u0646 \u0627\u0633\u062a\u062b\u0646\u0627 \u0631\u0627 \u0645\u06cc\u200c\u062e\u0648\u0627\u0647\u062f.",
   "reasons": ["\u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc GBS \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0628\u0644\u06cc \u0628\u062f\u0648\u0646 \u0628\u0627\u06a9\u062a\u0631\u06cc\u0648\u0631\u06cc \u0641\u0639\u0644\u06cc \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u0642\u0637\u0639\u06cc \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u0646\u06cc\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d (\u0627\u0633\u062a\u062b\u0646\u0627).", "\u062a\u0648\u0644\u062f \u0646\u0648\u0632\u0627\u062f \u0642\u0628\u0644\u06cc \u0645\u0628\u062a\u0644\u0627 \u0628\u0647 \u0628\u06cc\u0645\u0627\u0631\u06cc GBS \u0627\u0632 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646\u200c\u0647\u0627\u06cc \u0642\u0637\u0639\u06cc \u0627\u0633\u062a.", "\u0632\u0627\u06cc\u0645\u0627\u0646 \u0632\u0648\u062f\u0631\u0633 \u067e\u06cc\u0634 \u0627\u0632 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u0627\u0633\u062a.", "\u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u0654 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u0628\u06cc\u0634 \u0627\u0632 \u06f1\u06f8 \u0633\u0627\u0639\u062a \u0627\u0646\u062f\u06cc\u06a9\u0627\u0633\u06cc\u0648\u0646 \u067e\u0631\u0648\u0641\u06cc\u0644\u0627\u06a9\u0633\u06cc \u0627\u0633\u062a."],
  },
  (28, 21): {
   "topic": "iutHydrops",
   "lead": "\u0645\u0627\u062f\u0631 Rh \u0645\u0646\u0641\u06cc \u0627\u06cc\u0645\u0646\u200c\u0634\u062f\u0647 \u0628\u0627 \u062c\u0646\u06cc\u0646 \u0647\u06cc\u062f\u0631\u0648\u067e\u06cc\u06a9 \u0648 \u0647\u0645\u0627\u062a\u0648\u06a9\u0631\u06cc\u062a \u062d\u062f\u0648\u062f \u06f2\u06f5\u066a \u062f\u0631 \u06a9\u0648\u0631\u062f\u0648\u0633\u0646\u062a\u0632: \u062a\u0632\u0631\u06cc\u0642 \u062e\u0648\u0646 \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u0628\u0647 \u062c\u0646\u06cc\u0646.",
   "interpretation": "\u062f\u0631 \u0627\u06cc\u0645\u0646\u200c\u0633\u0627\u0632\u06cc Rh \u0628\u0627 \u0622\u0646\u062a\u06cc\u200c\u0628\u0627\u062f\u06cc \u062a\u062b\u0628\u06cc\u062a\u200c\u0634\u062f\u0647 (\u06a9\u0648\u0645\u0628\u0633 \u063a\u06cc\u0631\u0645\u0633\u062a\u0642\u06cc\u0645 \u0645\u062b\u0628\u062a) \u0648\u0642\u062a\u06cc \u062c\u0646\u06cc\u0646 \u0647\u06cc\u062f\u0631\u0648\u067e\u0633 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u062f\u0627\u0631\u062f \u0648 \u0646\u0645\u0648\u0646\u0647\u200c\u0628\u0631\u062f\u0627\u0631\u06cc \u062e\u0648\u0646 \u0627\u0632 \u0628\u0646\u062f \u0646\u0627\u0641 \u0647\u0645\u0627\u062a\u0648\u06a9\u0631\u06cc\u062a \u067e\u0627\u06cc\u06cc\u0646 (\u06f2\u06f5\u066a) \u0631\u0627 \u062a\u0623\u06cc\u06cc\u062f \u0645\u06cc\u200c\u06a9\u0646\u062f\u060c \u062f\u0631\u0645\u0627\u0646 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062a\u0628\u0627\u062f\u0644/\u062a\u0632\u0631\u06cc\u0642 \u062e\u0648\u0646 \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc (IUT) \u062f\u0631 \u062f\u0631\u0648\u0646 \u0631\u06af \u0646\u0627\u0641 \u062a\u062d\u062a \u0647\u062f\u0627\u06cc\u062a \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc \u0627\u0633\u062a \u062a\u0627 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u062c\u062f\u06cc \u062c\u0646\u06cc\u0646\u06cc \u0628\u0631\u0637\u0631\u0641 \u0634\u0648\u062f \u0648 \u0628\u0647 \u0645\u0631\u06af \u062c\u0646\u06cc\u0646 \u0646\u0631\u0633\u062f\u061b \u062e\u062a\u0645 \u062d\u0627\u0645\u0644\u06af\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a\u060c \u062f\u0627\u067e\u0644\u0631 MCA \u0627\u0628\u0632\u0627\u0631 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u0627\u0633\u062a \u0646\u0647 \u062f\u0631\u0645\u0627\u0646 \u0648 \u0631\u0648\u06af\u0627\u0645 \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 (\u062d\u0633\u0627\u0633\u200c\u0634\u062f\u0647) \u06a9\u0627\u0631\u0628\u0631\u062f \u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u062f\u0627\u0631\u062f.",
   "reasons": ["\u062a\u0632\u0631\u06cc\u0642 \u062e\u0648\u0646 \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc \u062f\u0631\u0645\u0627\u0646 \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0634\u062f\u06cc\u062f \u062c\u0646\u06cc\u0646\u06cc \u0646\u0627\u0634\u06cc \u0627\u0632 \u0627\u06cc\u0645\u0646\u200c\u0633\u0627\u0632\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062e\u062a\u0645 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646 \u0642\u0628\u0644 \u0627\u0632 \u0627\u0645\u06a9\u0627\u0646 IUT \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0646\u06cc\u0633\u062a.", "\u062f\u0627\u067e\u0644\u0631 \u0634\u0631\u06cc\u0627\u0646 \u0645\u063a\u0632\u06cc \u0645\u06cc\u0627\u0646\u06cc \u0627\u0628\u0632\u0627\u0631 \u063a\u0631\u0628\u0627\u0644\u06af\u0631\u06cc \u06a9\u0645\u200c\u062e\u0648\u0646\u06cc \u0627\u0633\u062a \u0646\u0647 \u062f\u0631\u0645\u0627\u0646.", "\u0631\u0648\u06af\u0627\u0645 \u062f\u0631 \u0645\u0627\u062f\u0631 \u0642\u0628\u0644\u0627\u064b \u062d\u0633\u0627\u0633\u200c\u0634\u062f\u0647 \u0627\u062b\u0631 \u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 22): {
   "topic": "twinShortCervixManagement",
   "lead": "\u06af\u0631\u062f\u0646\u200c\u0631\u062d\u0645 \u06a9\u0648\u062a\u0627\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc: \u0634\u0648\u0627\u0647\u062f \u0633\u0648\u062f \u0633\u0631\u06a9\u0644\u0627\u0698\u060c \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0648 \u067e\u0633\u0627\u0631\u06cc \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a\u061b \u06a9\u0644\u06cc\u062f \u0645\u062f\u06cc\u0631\u06cc\u062a\u06cc \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634\u060c \u0627\u0635\u0644\u0627\u062d \u0634\u06cc\u0648\u0647\u0654 \u06a9\u0627\u0631/\u0641\u0639\u0627\u0644\u06cc\u062a \u0648 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u0627\u0633\u062a.",
   "interpretation": "\u0628\u0631\u062e\u0644\u0627\u0641 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062a\u06a9\u200c\u0642\u0644\u0648\u06cc\u06cc \u06a9\u0647 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u06cc\u0627 \u0633\u0631\u06a9\u0644\u0627\u0698 \u062f\u0631 \u06af\u0631\u062f\u0646\u200c\u0631\u062d\u0645 \u06a9\u0648\u062a\u0627\u0647 \u062c\u0627\u06cc\u06af\u0627\u0647 \u062f\u0627\u0631\u0646\u062f\u060c \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u0645\u0632\u0627\u06cc\u0627\u06cc \u0627\u06cc\u0646 \u0645\u062f\u0627\u062e\u0644\u0627\u062a \u0627\u062b\u0628\u0627\u062a\u200c\u0646\u0634\u062f\u0647 \u06cc\u0627 \u0645\u062d\u062f\u0648\u062f \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0633\u06cc\u0627\u0631\u06cc \u0627\u0632 \u0631\u0627\u0647\u0646\u0645\u0627\u0647\u0627 \u062a\u0648\u0635\u06cc\u0647 \u0631\u0648\u062a\u06cc\u0646 \u0646\u0645\u06cc\u200c\u0634\u0648\u0646\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0686\u0646\u06cc\u0646 \u067e\u0631\u0633\u0634\u06cc \u0627\u0642\u062f\u0627\u0645 \u067e\u06cc\u0634\u0646\u0647\u0627\u062f\u06cc \u06a9\u0644\u06cc\u062f\u060c \u0627\u0635\u0644\u0627\u062d \u0633\u0628\u06a9 \u06a9\u0627\u0631 \u0648 \u0641\u0639\u0627\u0644\u06cc\u062a \u0648 \u067e\u0627\u06cc\u0634 \u0645\u06a9\u0631\u0631 (\u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u0637\u0648\u0644 \u0633\u0631\u0648\u06cc\u06a9\u0633/\u0639\u0644\u0627\u06cc\u0645) \u0627\u0633\u062a \u0648 \u0627\u0642\u062f\u0627\u0645\u0627\u062a \u062a\u0647\u0627\u062c\u0645\u06cc \u062f\u0631 \u0627\u062b\u0631\u0628\u062e\u0634\u06cc \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u062a\u0648\u062c\u06cc\u0647\u200c\u0634\u062f\u0647 \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u0633\u0631\u06a9\u0644\u0627\u0698 \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u0628\u0627 \u06af\u0631\u062f\u0646\u200c\u0631\u062d\u0645 \u06a9\u0648\u062a\u0627\u0647 \u0633\u0648\u062f\u06cc \u0627\u062b\u0628\u0627\u062a\u200c\u0634\u062f\u0647\u0654 \u062b\u0627\u0628\u062a\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u0628\u0631\u062e\u0644\u0627\u0641 \u062a\u06a9\u200c\u0642\u0644\u0648 \u062a\u0648\u0635\u06cc\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0646\u06cc\u0633\u062a.", "\u0627\u0635\u0644\u0627\u062d \u06a9\u0627\u0631/\u0641\u0639\u0627\u0644\u06cc\u062a \u0648 \u067e\u06cc\u06af\u06cc\u0631\u06cc \u0633\u0648\u0646\u0648\u06af\u0631\u0627\u0641\u06cc\u06a9 \u062f\u0631 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f \u062f\u0631\u0633\u062a\u200c\u062a\u0631\u06cc\u0646 \u0627\u0642\u062f\u0627\u0645 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u067e\u0633\u0627\u0631\u06cc \u062f\u0631 \u062f\u0648\u0642\u0644\u0648\u06cc\u06cc \u0634\u0648\u0627\u0647\u062f \u0645\u062d\u062f\u0648\u062f\u06cc \u062f\u0627\u0631\u062f \u0648 \u062a\u0648\u0635\u06cc\u0647\u0654 \u0631\u0648\u062a\u06cc\u0646 \u0646\u06cc\u0633\u062a."],
  },
  (28, 24): {
   "topic": "previaExpectantSteroid",
   "lead": "\u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u062f\u0631 \u06f3\u06f3 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062e\u0641\u06cc\u0641 \u0648 \u0639\u0644\u0627\u0626\u0645 \u062d\u06cc\u0627\u062a\u06cc \u0648 \u062c\u0646\u06cc\u0646 \u0646\u0631\u0645\u0627\u0644: \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc + \u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u0628\u0631\u0627\u06cc \u0628\u0644\u0648\u063a \u0631\u06cc\u0647.",
   "interpretation": "\u0647\u0631 \u0632\u062e\u0645\u06cc \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0627\u0632 \u0645\u062d\u0644 \u062c\u0641\u062a \u067e\u06cc\u0634\u200c\u0631\u0648\u0646\u062f\u0647 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0637\u0631\u0646\u0627\u06a9 \u0627\u0633\u062a \u0627\u0645\u0627 \u0627\u06af\u0631 \u0645\u0627\u062f\u0631 \u067e\u0627\u06cc\u062f\u0627\u0631 \u0648 \u062c\u0646\u06cc\u0646 \u062f\u0631 \u0648\u0636\u0639\u06cc\u062a \u062e\u0648\u0628 \u0627\u0633\u062a \u0648 \u0633\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u067e\u06cc\u0634\u200c\u062a\u0631 \u0627\u0632 \u062a\u0631\u0645 \u0627\u0633\u062a\u060c \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062e\u0641\u06cc\u0641 \u0645\u062a\u0648\u0642\u0641\u200c\u0634\u062f\u0647 \u0631\u0648\u06cc\u06a9\u0631\u062f \u067e\u0630\u06cc\u0631\u0641\u062a\u0647\u200c\u0634\u062f\u0647\u060c \u0628\u0633\u062a\u0631\u06cc/\u0645\u0631\u0627\u0642\u0628\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0628\u0627 \u062a\u062c\u0648\u06cc\u0632 \u0628\u062a\u0627\u0645\u062a\u0627\u0632\u0648\u0646/\u062f\u06af\u0632\u0627\u0645\u062a\u0627\u0632\u0648\u0646 \u0628\u0631\u0627\u06cc \u0628\u0644\u0648\u063a \u0631\u06cc\u0647\u0654 \u062c\u0646\u06cc\u0646 \u062a\u0627 \u0628\u0647 \u0628\u0644\u0648\u063a \u0628\u0631\u0633\u062f \u06cc\u0627 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0634\u062f\u06cc\u062f \u0645\u062c\u062f\u062f \u0631\u062e \u062f\u0647\u062f\u060c \u0627\u0633\u062a\u061b \u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f\u060c \u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u0645\u0645\u0646\u0648\u0639 \u0648 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0642\u0637 \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0634\u062f\u06cc\u062f \u06cc\u0627 \u062f\u06cc\u0633\u062a\u0631\u0633 \u0644\u0627\u0632\u0645 \u0627\u0633\u062a.",
   "reasons": ["\u06a9\u0648\u0631\u062a\u06cc\u06a9\u0648\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f \u062f\u0631 \u06f3\u06f3 \u0647\u0641\u062a\u0647 \u0628\u0631\u0627\u06cc \u0628\u0644\u0648\u063a \u0631\u06cc\u0647 \u062f\u0631 \u0645\u062f\u06cc\u0631\u06cc\u062a \u0627\u0646\u062a\u0638\u0627\u0631\u06cc \u0645\u0637\u0631\u062d \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062a\u0648\u06a9\u0648\u0644\u06cc\u062a\u06cc\u06a9 \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0646\u0627\u0634\u06cc \u0627\u0632 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u062a\u0648\u0635\u06cc\u0647 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0627\u0644\u0642\u0627\u06cc \u0632\u0627\u06cc\u0645\u0627\u0646 \u062f\u0631 \u062c\u0641\u062a \u0633\u0631\u0631\u0627\u0647\u06cc \u06a9\u0627\u0645\u0644 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u0648\u0631\u0698\u0627\u0646\u0633 \u0641\u0642\u0637 \u062f\u0631 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u0634\u062f\u06cc\u062f \u06cc\u0627 \u0646\u0627\u067e\u0627\u06cc\u062f\u0627\u0631\u06cc \u0644\u0627\u0632\u0645 \u0627\u0633\u062a."],
  },
  (28, 26): {
   "topic": "pregnancyVaccines",
   "lead": "\u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u0632\u0646\u062f\u0647 (\u0633\u0631\u062e\u062c\u0647\u060c \u0627\u0648\u0631\u06cc\u0648\u0646/MMR\u060c \u062a\u0628 \u0632\u0631\u062f) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f\u061b \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0641\u0635\u0644\u06cc \u0645\u062c\u0627\u0632 \u0648 \u062a\u0648\u0635\u06cc\u0647\u200c\u0634\u062f\u0647 \u0627\u0633\u062a.",
   "interpretation": "\u0648\u0627\u06a9\u0633\u0646\u200c\u0647\u0627\u06cc \u0632\u0646\u062f\u0647\u0654 \u062a\u0636\u0639\u06cc\u0641\u200c\u0634\u062f\u0647 (MMR/\u0633\u0631\u062e\u062c\u0647/\u0627\u0648\u0631\u06cc\u0648\u0646 \u0648 \u062a\u0628 \u0632\u0631\u062f) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u062e\u0637\u0631 \u0646\u0638\u0631\u06cc \u0639\u0641\u0648\u0646\u062a \u062c\u0646\u06cc\u0646\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632 \u0642\u0628\u0644 \u0627\u0632 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u06cc\u0627 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u062a\u0632\u0631\u06cc\u0642 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0648 \u0631\u0648\u0627\u0644 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0622\u0646\u200c\u0647\u0627 \u0645\u0639\u0645\u0648\u0644 \u0627\u0633\u062a\u061b \u062f\u0631 \u0645\u0642\u0627\u0628\u0644 \u0648\u0627\u06a9\u0633\u0646 \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627\u06cc \u062a\u0632\u0631\u06cc\u0642\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u0641\u0635\u0644\u06cc \u062f\u0631 \u0647\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647 \u0627\u06cc\u0645\u0646 \u0627\u0633\u062a \u0648 \u0628\u0647\u200c\u0637\u0648\u0631 \u0641\u0639\u0627\u0644 \u062a\u0648\u0635\u06cc\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f \u0686\u0648\u0646 \u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u062f \u0634\u062f\u06cc\u062f\u062a\u0631 \u0628\u0627\u0634\u062f.",
   "reasons": ["\u0633\u0631\u062e\u062c\u0647 \u0648\u0627\u06a9\u0633\u0646 \u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.", "\u062a\u0628 \u0632\u0631\u062f \u0648\u0627\u06a9\u0633\u0646 \u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062c\u0632 \u062f\u0631 \u0647\u0645\u0647\u200c\u06af\u06cc\u0631\u06cc \u0628\u0627 \u0627\u062c\u0627\u0632\u0647 \u062e\u0627\u0635 \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.", "\u0622\u0646\u0641\u0644\u0648\u0622\u0646\u0632\u0627\u06cc \u06a9\u0634\u062a\u0647\u200c\u0634\u062f\u0647\u0654 \u062a\u0632\u0631\u06cc\u0642\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u062c\u0627\u0632 \u0648 \u062a\u0648\u0635\u06cc\u0647 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u0648\u0631\u06cc\u0648\u0646 (MMR) \u0648\u0627\u06a9\u0633\u0646 \u0632\u0646\u062f\u0647 \u0627\u0633\u062a \u0648 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a."],
  },
  (28, 29): {
   "topic": "septicAbortionManage",
   "lead": "\u062a\u0628 + \u062a\u0631\u0634\u062d \u0628\u062f\u0628\u0648 + \u062a\u0646\u062f\u0631\u0646\u0633 \u0631\u062d\u0645\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u0627\u062e\u0648\u0627\u0633\u062a\u0647\u0654 \u06f8 \u0647\u0641\u062a\u0647 \u0628\u0627 \u062c\u0646\u06cc\u0646 \u0632\u0646\u062f\u0647: \u0648\u0641\u0648\u0631 \u0639\u0641\u0648\u0646\u062a \u062f\u0627\u062e\u0644\u200c\u0631\u062d\u0645\u06cc (\u0633\u0642\u0637 \u0633\u067e\u062a\u06cc\u06a9)\u061b \u067e\u0633 \u0627\u0632 \u0645\u0627\u06cc\u0639\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0648 \u067e\u0627\u06cc\u062f\u0627\u0631\u0633\u0627\u0632\u06cc\u060c \u062a\u062e\u0644\u06cc\u0647\u0654 \u0631\u062d\u0645 \u06a9\u0646\u062a\u0631\u0644 \u0645\u0646\u0628\u0639 \u0627\u0633\u062a \u0648 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0648\u0633\u06cc\u0639\u200c\u0627\u0644\u0637\u06cc\u0641 \u062d\u062a\u0645\u06cc.",
   "interpretation": "\u0633\u0642\u0637 \u0639\u0641\u0648\u0646\u06cc/\u0633\u067e\u062a\u06cc\u06a9 \u0627\u0636\u0637\u0631\u0627\u0631\u06cc \u0627\u0633\u062a: \u0639\u0644\u0627\u06cc\u0645 \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9 (\u062a\u0628)\u060c \u062a\u0631\u0634\u062d \u0628\u062f\u0628\u0648 \u0648 \u062d\u0633\u0627\u0633\u06cc\u062a \u0631\u062d\u0645\u06cc \u0647\u0645\u0631\u0627\u0647 \u0628\u0642\u0627\u06cc\u0627\u06cc \u062d\u0627\u0645\u0644\u06af\u06cc/\u062c\u0646\u06cc\u0646 \u0632\u0646\u062f\u0647 \u062a\u0639\u0631\u06cc\u0641 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0628\u0639\u062f \u0627\u0632 \u0627\u062d\u06cc\u0627\u06cc \u0628\u06cc\u0645\u0627\u0631 (\u0645\u0627\u06cc\u0639\u200c\u062f\u0631\u0645\u0627\u0646\u06cc\u060c \u067e\u0627\u06cc\u062f\u0627\u0631\u0633\u0627\u0632\u06cc \u0639\u0644\u0627\u0626\u0645 \u062d\u06cc\u0627\u062a\u06cc) \u0647\u0631 \u062f\u0648 \u0627\u0642\u062f\u0627\u0645 \u00ab\u0634\u0631\u0648\u0639 \u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0648\u0633\u06cc\u0639\u200c\u0627\u0644\u0637\u06cc\u0641\u00bb \u0648 \u00ab\u062a\u062e\u0644\u06cc\u0647\u0654 \u0633\u0631\u06cc\u0639 \u0645\u062d\u062a\u0648\u06cc\u0627\u062a \u0631\u062d\u0645\u00bb \u0644\u0627\u0632\u0645\u200c\u0627\u0646\u062f \u0648 \u062f\u0631 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f\u060c \u06a9\u0648\u0631\u062a\u0627\u0698 \u062a\u062e\u0644\u06cc\u0647\u200c\u0627\u06cc \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u06a9\u0646\u062a\u0631\u0644 \u0645\u0646\u0628\u0639 \u0639\u0641\u0648\u0646\u062a \u062f\u0631 \u06af\u0632\u06cc\u0646\u0647\u0654 \u0627\u0648\u0644\u06cc\u0647 \u0642\u0631\u0627\u0631 \u06af\u0631\u0641\u062a\u0647 \u0627\u0633\u062a\u061b \u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u062d\u0636\u0648\u0631 \u0639\u0641\u0648\u0646\u062a \u062f\u06cc\u0631 \u0648 \u0646\u0627\u06a9\u0627\u0641\u06cc \u0627\u0633\u062a \u0648 \u06af\u0631\u0627\u0641\u06cc \u0634\u06a9\u0645 \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u062a\u0634\u062e\u06cc\u0635\u06cc \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u062a\u062e\u0644\u06cc\u0647\u0654 \u0631\u062d\u0645 (\u06a9\u0646\u062a\u0631\u0644 \u0645\u0646\u0628\u0639) \u0628\u0647\u200c\u0647\u0645\u0631\u0627\u0647/\u067e\u0633 \u0627\u0632 \u067e\u0627\u06cc\u062f\u0627\u0631\u0633\u0627\u0632\u06cc \u0627\u0642\u062f\u0627\u0645 \u06a9\u0644\u06cc\u062f\u06cc \u062f\u0631 \u0633\u0642\u0637 \u0633\u067e\u062a\u06cc\u06a9 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0645\u06cc\u0632\u0648\u067e\u0631\u0648\u0633\u062a\u0648\u0644 \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u0639\u0641\u0648\u0646\u062a \u062c\u0627\u0631\u06cc \u0646\u0627\u06a9\u0627\u0641\u06cc \u0648 \u06a9\u0646\u062f \u0627\u0633\u062a.", "\u0622\u0646\u062a\u06cc\u200c\u0628\u06cc\u0648\u062a\u06cc\u06a9 \u0628\u062f\u0648\u0646 \u062a\u062e\u0644\u06cc\u0647\u0654 \u0628\u0642\u0627\u06cc\u0627\u06cc \u0622\u0644\u0648\u062f\u0647 \u06a9\u0646\u062a\u0631\u0644 \u06a9\u0627\u0645\u0644 \u0645\u0646\u0628\u0639 \u0646\u06cc\u0633\u062a.", "\u06af\u0631\u0627\u0641\u06cc \u0634\u06a9\u0645 \u062f\u0631 \u062a\u0634\u062e\u06cc\u0635 \u0627\u06cc\u0646 \u0633\u0646\u0627\u0631\u06cc\u0648 \u0646\u0642\u0634 \u0645\u062d\u062f\u0648\u062f\u06cc \u062f\u0627\u0631\u062f."],
  },
  (28, 31): {
   "topic": "gtnRuleOutNewPregnancy",
   "lead": "\u0635\u0639\u0648\u062f \u0645\u062c\u062f\u062f BHCG \u067e\u0633 \u0627\u0632 \u0633\u0627\u06a9\u0634\u0646 \u0645\u0648\u0644 (\u06f1\u06f0\u06f0\u06f0 \u0628\u0647 \u06f2\u06f5\u06f0\u06f0): \u067e\u06cc\u0634 \u0627\u0632 \u0647\u0631 \u062f\u0631\u0645\u0627\u0646\u060c \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u0631\u0627 \u0631\u062f \u06a9\u0646.",
   "interpretation": "\u067e\u0633 \u0627\u0632 \u062a\u062e\u0644\u06cc\u0647\u0654 \u0645\u0648\u0644\u060c \u067e\u0627\u06cc\u0634 \u0647\u0641\u062a\u06af\u06cc BHCG \u0628\u0627\u06cc\u062f \u0631\u0648\u0646\u062f \u0646\u0632\u0648\u0644\u06cc \u0646\u0634\u0627\u0646 \u062f\u0647\u062f\u061b \u0647\u0631 \u067e\u0644\u0627\u062a\u0648 \u06cc\u0627 \u0635\u0639\u0648\u062f\u0650 BHCG\u060c \u0627\u062d\u062a\u0645\u0627\u0644 \u0628\u06cc\u0645\u0627\u0631\u06cc \u062a\u0631\u0648\u0641\u0648\u0628\u0644\u0627\u0633\u062a\u06cc\u06a9 \u0645\u0627\u062f\u0631\u0632\u0627\u062f\u06cc \u067e\u0627\u06cc\u062f\u0627\u0631 (GTN) \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0627\u0645\u0627 \u0627\u0648\u0644\u06cc\u0646 \u0642\u062f\u0645 \u0627\u0635\u0648\u0644\u06cc\u060c \u0631\u062f \u06a9\u0631\u062f\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f (\u0645\u0645\u06a9\u0646 \u0627\u0633\u062a \u067e\u0633 \u0627\u0632 \u06a9\u0646\u062a\u0631\u0644 \u0628\u0627\u0631\u0648\u0631\u06cc \u0645\u0648\u0641\u0642 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f\u06cc \u0631\u062e \u062f\u0627\u062f\u0647 \u0628\u0627\u0634\u062f) \u0627\u0633\u062a \u0686\u0648\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0637\u0628\u06cc\u0639\u06cc \u062c\u062f\u06cc\u062f \u0646\u06cc\u0632 BHCG \u0635\u0639\u0648\u062f\u06cc \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u062f\u0631\u0645\u0627\u0646\u200c\u0647\u0627\u06cc \u0634\u06cc\u0645\u06cc\u200c\u062f\u0631\u0645\u0627\u0646\u06cc/\u06a9\u0648\u0631\u062a\u0627\u0698/\u062a\u06a9\u0631\u0627\u0631 \u0628\u0631 \u067e\u0627\u06cc\u0647\u0654 \u0627\u06cc\u0646 \u062a\u0645\u0627\u06cc\u0632 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0633 \u0627\u0632 \u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u0648 \u0633\u0627\u06cc\u0631 \u0639\u0644\u0644\u060c \u0645\u062f\u06cc\u0631\u06cc\u062a GTN \u0622\u063a\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u067e\u06cc\u0634 \u0627\u0632 \u0647\u0631 \u0642\u062f\u0645 \u062f\u06cc\u06af\u0631 \u0627\u0642\u062f\u0627\u0645 \u0645\u0646\u0637\u0642\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0645\u0648\u062a\u0631\u0627\u067e\u06cc \u0641\u0642\u0637 \u067e\u0633 \u0627\u0632 \u0631\u062f \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062c\u062f\u06cc\u062f \u0648 \u062a\u0623\u06cc\u06cc\u062f GTN \u0634\u0631\u0648\u0639 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u06a9\u0648\u0631\u062a\u0627\u0698 \u0645\u062c\u062f\u062f \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631\u0645\u0627\u0646 \u0635\u0639\u0648\u062f BHCG \u067e\u0633 \u0627\u0632 \u0633\u0627\u06a9\u0634\u0646 \u0646\u06cc\u0633\u062a.", "\u062a\u06a9\u0631\u0627\u0631 BHCG \u0628\u0647\u200c\u062a\u0646\u0647\u0627\u06cc\u06cc \u062f\u0631 \u0635\u0639\u0648\u062f \u063a\u06cc\u0631\u0642\u0627\u0628\u0644\u200c\u0627\u0646\u06a9\u0627\u0631 \u062a\u0635\u0645\u06cc\u0645\u200c\u0633\u0627\u0632 \u0646\u06cc\u0633\u062a."],
  },
  (28, 33): {
   "topic": "ocpCancerEffects",
   "lead": "\u0645\u0635\u0631\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc \u0642\u0631\u0635\u200c\u0647\u0627\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0636\u062f\u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u062e\u0637\u0631 \u0622\u062f\u0646\u0648\u0645 \u06a9\u0628\u062f \u0631\u0627 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f \u0627\u0645\u0627 \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646\u200c\u0647\u0627\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0648 \u062a\u062e\u0645\u062f\u0627\u0646 (\u0648 \u0627\u062d\u062a\u0645\u0627\u0644\u0627\u064b \u06a9\u0648\u0644\u0648\u0646) \u0631\u0627 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u062f.",
   "interpretation": "\u0642\u0631\u0635\u200c\u0647\u0627\u06cc \u062a\u0631\u06a9\u06cc\u0628\u06cc \u062e\u0648\u0631\u0627\u06a9\u06cc \u0628\u0647\u200c\u062f\u0644\u06cc\u0644 \u062f\u0627\u0634\u062a\u0646 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646\u060c \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0631\u0627 \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u062f\u0647\u0646\u062f \u0648 \u0628\u0627 \u0633\u0631\u06a9\u0648\u0628 \u062a\u062e\u0645\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0627\u067e\u06cc\u062a\u0644\u06cc\u0627\u0644 \u062a\u062e\u0645\u062f\u0627\u0646 \u0631\u0627 \u067e\u0627\u06cc\u06cc\u0646 \u0645\u06cc\u200c\u0622\u0648\u0631\u0646\u062f \u0648 \u0634\u0648\u0627\u0647\u062f \u06a9\u0627\u0647\u0634 \u062e\u0637\u0631 \u06a9\u0648\u0644\u0648\u0631\u06a9\u062a\u0627\u0644 \u0646\u06cc\u0632 \u06af\u0632\u0627\u0631\u0634 \u0634\u062f\u0647\u200c\u0627\u0633\u062a\u061b \u062f\u0631 \u0645\u0642\u0627\u0628\u0644\u060c \u0622\u062f\u0646\u0648\u0645 \u0647\u067e\u0627\u062a\u0648\u0633\u0644\u0648\u0644\u0627\u0631 \u06a9\u0628\u062f (\u062a\u0648\u062f\u0647\u0654 \u062e\u0648\u0634\u200c\u062e\u06cc\u0645 \u0648 \u062f\u0631 \u0645\u0639\u0631\u0636 \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc) \u0628\u0627 \u0645\u0635\u0631\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc\u200c\u0645\u062f\u062a \u0627\u0633\u062a\u0631\u0648\u0698\u0646\u200c\u0647\u0627\u06cc \u062e\u0648\u0631\u0627\u06a9\u06cc \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f \u0648 \u0647\u0645\u0627\u0646 \u00ab\u062a\u0648\u0645\u0648\u0631 \u0627\u0641\u0632\u0627\u06cc\u0634\u200c\u06cc\u0627\u0641\u062a\u0647\u0654 \u0628\u0627\u0631\u0632 \u0628\u0627 OCP\u00bb \u0627\u0633\u062a.",
   "reasons": ["\u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u0622\u0646\u062f\u0648\u0645\u062a\u0631 \u0628\u0627 OCP \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f \u0646\u0647 \u0627\u0641\u0632\u0627\u06cc\u0634.", "\u062e\u0637\u0631 \u0633\u0631\u0637\u0627\u0646 \u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0627 \u0645\u0635\u0631\u0641 OCP \u06a9\u0627\u0647\u0634 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f \u0648 \u0627\u06cc\u0646 \u06af\u0632\u06cc\u0646\u0647 \u0646\u0627\u062f\u0631\u0633\u062a \u0627\u0633\u062a.", "\u0622\u062f\u0646\u0648\u0645 \u06a9\u0628\u062f \u0628\u0627 \u0645\u0635\u0631\u0641 \u0637\u0648\u0644\u0627\u0646\u06cc \u0627\u0633\u062a\u0631\u0648\u0698\u0646 \u062a\u0631\u06a9\u06cc\u0628\u06cc \u0627\u0641\u0632\u0627\u06cc\u0634 \u0645\u06cc\u200c\u06cc\u0627\u0628\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u06a9\u0648\u0644\u0648\u0646 \u0647\u0645 \u062a\u062d\u062a \u062a\u0623\u062b\u06cc\u0631 \u0645\u062d\u0627\u0641\u0638\u062a\u06cc \u06af\u0632\u0627\u0631\u0634 \u0634\u062f\u0647 \u0646\u0647 \u0627\u0641\u0632\u0627\u06cc\u0634\u06cc."],
  },
  (28, 34): {
   "topic": "prematureOvarianInsufficiency",
   "lead": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u062b\u0627\u0646\u0648\u06cc\u0647\u0654 \u067e\u0627\u0633\u062e \u0645\u0646\u0641\u06cc \u0628\u0647 \u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0628\u0627 FSH \u0628\u0627\u0644\u0627 (\u06f1\u06f0\u06f0) \u062f\u0631 \u0632\u0646 \u06f2\u06f6 \u0633\u0627\u0644\u0647: \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654 \u062a\u062e\u0645\u062f\u0627\u0646\u061b \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e.",
   "interpretation": "\u0622\u0645\u0646\u0648\u0631\u0647\u0654 \u062b\u0627\u0646\u0648\u06cc\u0647 \u0628\u0627 \u0646\u0628\u0648\u062f \u062e\u0648\u0646\u200c\u0631\u06cc\u0632\u06cc \u067e\u0633 \u0627\u0632-\u067e\u0631\u0648\u0698\u0633\u062a\u0631\u0648\u0646 \u0648 \u0633\u0637\u062d \u0627\u0633\u062a\u0631\u0627\u062f\u06cc\u0648\u0644 \u067e\u0627\u06cc\u06cc\u0646 \u0647\u0645\u0631\u0627\u0647 FSH \u0628\u0627\u0644\u0627 (\u0628\u06cc\u0634\u200c\u062a\u0631 \u0627\u0632 \u06f2\u06f5-\u06f4\u06f0) \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u0654/\u0632\u0648\u062f\u0631\u0633 \u062a\u062e\u0645\u062f\u0627\u0646 (POI) \u0627\u0633\u062a\u061b \u062f\u0631 \u0627\u06cc\u0646 \u0633\u0646\u060c \u0628\u0631\u0631\u0633\u06cc \u0639\u0644\u0644 \u0698\u0646\u062a\u06cc\u06a9\u06cc (\u0645\u062b\u0644 45X \u0648 \u0645\u0648\u0632\u0627\u06cc\u06cc\u06a9)\u060c \u062a\u062e\u0645\u062f\u0627\u0646 \u062e\u0648\u062f\u0627\u06cc\u0645\u0646\u06cc \u0648 \u0633\u0627\u06cc\u0631 \u0639\u0644\u0644 \u0628\u0627 \u0627\u0646\u062c\u0627\u0645 \u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u0622\u063a\u0627\u0632 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646\u06cc \u0647\u0648\u0631\u0645\u0648\u0646\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u0641\u0627\u0632 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a \u0648 MRI \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 \u062f\u0631 \u063a\u06cc\u0627\u0628 \u0639\u0644\u0627\u06cc\u0645 \u0641\u0634\u0631\u062f\u0647\u200c\u0633\u0627\u0632\u06cc/\u067e\u0631\u0648\u0644\u0627\u06a9\u062a\u06cc\u0646 \u0628\u0627\u0644\u0627/\u06a9\u0627\u0647\u0634 \u06af\u0646\u0627\u062f\u0648\u062a\u0631\u0648\u067e\u06cc\u0646 \u0644\u0627\u0632\u0645 \u0646\u06cc\u0633\u062a \u0648 \u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062f\u0631 \u0633\u0646\u062f\u0631\u0645 \u0622\u0634\u0631\u0645\u0646 (\u06a9\u0648\u0631\u062a\u0627\u0698 \u0642\u0628\u0644\u06cc) \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u0634\u0648\u062f \u0646\u0647 \u062f\u0631 POI.",
   "reasons": ["\u0647\u0648\u0631\u0645\u0648\u0646\u200c\u062f\u0631\u0645\u0627\u0646\u06cc \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u0641\u0627\u0632 \u062f\u0631\u0645\u0627\u0646\u06cc \u0628\u0639\u062f \u0627\u0632 \u062a\u0634\u062e\u06cc\u0635 \u0627\u0633\u062a\u060c \u0646\u0647 \u0642\u062f\u0645 \u0628\u0639\u062f\u06cc \u062a\u0634\u062e\u06cc\u0635\u06cc.", "\u0647\u06cc\u0633\u062a\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0628\u0631\u0627\u06cc \u0622\u0634\u0631\u0645\u0646 \u0627\u0633\u062a \u0646\u0647 \u0628\u0631\u0627\u06cc \u0646\u0627\u0631\u0633\u0627\u06cc\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0628\u0627 FSH \u0628\u0627\u0644\u0627.", "\u06a9\u0627\u0631\u06cc\u0648\u062a\u0627\u06cc\u067e \u0628\u0631\u0627\u06cc \u0628\u0631\u0631\u0633\u06cc \u0639\u0644\u0644 \u0698\u0646\u062a\u06cc\u06a9\u06cc POI \u062f\u0631 \u0633\u0646 \u062c\u0648\u0627\u0646 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "MRI \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632 \u062f\u0631 \u0627\u06cc\u0646 \u067e\u0631\u0648\u0641\u0627\u06cc\u0644 \u0628\u062f\u0648\u0646 \u0639\u0644\u0627\u06cc\u0645 \u0645\u062d\u0648\u0631 \u0647\u06cc\u067e\u0648\u0641\u06cc\u0632\u06cc \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644 \u0646\u06cc\u0633\u062a."],
  },
  (28, 35): {
   "topic": "trichomoniasisRetreat",
   "lead": "\u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0628\u0627 \u06cc\u06a9 \u062f\u0648\u0631\u0647\u0654 \u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u06f5\u06f0\u06f0 \u062f\u0648\u0628\u0627\u0631 \u062f\u0631 \u0631\u0648\u0632 \u0647\u0641\u062a\u200c\u0631\u0648\u0632\u0647 \u067e\u0627\u0633\u062e \u0646\u062f\u0627\u062f\u0647: \u062a\u06a9\u0631\u0627\u0631 \u0647\u0645\u0627\u0646 \u0631\u0698\u06cc\u0645 (\u062f\u0648\u0631\u0647\u0654 \u062f\u0648\u0645 \u06f5\u06f0\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062f\u0648\u0628\u0627\u0631 \u062f\u0631 \u0631\u0648\u0632 \u0628\u0631\u0627\u06cc \u0647\u0641\u062a \u0631\u0648\u0632).",
   "interpretation": "\u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u06a9\u0644\u0627\u0633\u06cc\u06a9 \u0628\u0631\u0627\u06cc \u0646\u062e\u0633\u062a\u06cc\u0646 \u0639\u0648\u062f/\u0646\u0627\u06a9\u0627\u0645\u06cc \u062f\u0631\u0645\u0627\u0646 \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633\u060c \u062a\u06a9\u0631\u0627\u0631 \u0647\u0645\u0627\u0646 \u062f\u0648\u0631\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u06f5\u06f0\u06f0 \u0645\u06cc\u0644\u06cc\u200c\u06af\u0631\u0645 \u062e\u0648\u0631\u0627\u06a9\u06cc \u062f\u0648\u0628\u0627\u0631 \u062f\u0631 \u0631\u0648\u0632 \u0628\u0631\u0627\u06cc \u06f7 \u0631\u0648\u0632 \u0627\u0633\u062a (\u0642\u0628\u0644 \u0627\u0632 \u0627\u0641\u0632\u0627\u06cc\u0634 \u0628\u0647 \u062f\u0648\u0632 \u062f\u0648\u200c\u06af\u0631\u0645 \u0631\u0648\u0632\u0627\u0646\u0647 \u06cc\u0627 \u062a\u063a\u06cc\u06cc\u0631 \u0645\u0633\u06cc\u0631) \u0632\u06cc\u0631\u0627 \u0628\u062e\u0634 \u0642\u0627\u0628\u0644\u200c\u062a\u0648\u062c\u0647\u06cc \u0627\u0632 \u00ab\u0646\u0627\u06a9\u0627\u0645\u06cc\u200c\u0647\u0627\u00bb \u0639\u0641\u0648\u0646\u062a \u0645\u062c\u062f\u062f \u06cc\u0627 \u0639\u062f\u0645 \u062a\u06a9\u0645\u06cc\u0644 \u0645\u0635\u0631\u0641 \u0627\u0633\u062a\u061b \u062f\u0648\u0632 \u0648\u0627\u062d\u062f \u06f2 \u06af\u0631\u0645 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u0645\u062a\u0648\u0627\u0644\u06cc \u06f3-\u06f5 \u0631\u0648\u0632 \u0631\u0698\u06cc\u0645 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a \u0648 \u0646\u0647 \u0642\u062f\u0645 \u0627\u0648\u0644\u061b \u0641\u0631\u0645\u200c\u0647\u0627\u06cc \u0645\u0648\u0636\u0639\u06cc \u0698\u0644 \u062c\u0630\u0628 \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9 \u06a9\u0627\u0641\u06cc \u0646\u062f\u0627\u0631\u0646\u062f \u0648 \u06a9\u0644\u06cc\u0646\u062f\u0627\u0645\u0627\u06cc\u0633\u06cc\u0646 \u0628\u0631\u0627\u06cc \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a.",
   "reasons": ["\u062a\u06a9\u0631\u0627\u0631 \u062f\u0648\u0631\u0647\u0654 \u06f5\u06f0\u06f0 \u00d7 \u062f\u0648\u0628\u0627\u0631 \u062f\u0631 \u0631\u0648\u0632 \u0647\u0641\u062a\u200c\u0631\u0648\u0632\u0647 \u0642\u062f\u0645 \u0627\u0648\u0644 \u0639\u0648\u062f \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u0633 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0698\u0644 \u0645\u0648\u0636\u0639\u06cc \u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u0628\u0631\u0627\u06cc \u062f\u0631\u0645\u0627\u0646 \u0633\u06cc\u0633\u062a\u0645\u06cc\u06a9 \u06a9\u0627\u0641\u06cc \u0646\u06cc\u0633\u062a.", "\u0645\u062a\u0631\u0648\u0646\u06cc\u062f\u0627\u0632\u0648\u0644 \u06f2 \u06af\u0631\u0645 \u0631\u0648\u0632\u0627\u0646\u0647 \u0633\u0647-\u067e\u0646\u062c \u0631\u0648\u0632 \u067e\u0644\u0647\u0654 \u0628\u0639\u062f\u06cc \u0627\u0633\u062a \u0646\u0647 \u0642\u062f\u0645 \u0627\u0648\u0644 \u062f\u0631 \u0627\u06cc\u0646 \u06a9\u0644\u06cc\u062f.", "\u06a9\u0644\u06cc\u0646\u062f\u0627\u0645\u0627\u06cc\u0633\u06cc\u0646 \u062f\u0631 \u062a\u0631\u06cc\u06a9\u0648\u0645\u0648\u0646\u0627\u06cc\u06cc \u062c\u0627\u06cc\u06af\u0627\u0647 \u0627\u062b\u0628\u0627\u062a\u200c\u0634\u062f\u0647 \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 36): {
   "topic": "magnesiumToxicity",
   "lead": "\u0645\u0633\u0645\u0648\u0645\u06cc\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 (\u0636\u0639\u0641 \u0639\u0636\u0644\u0627\u062a + \u0627\u062e\u062a\u0644\u0627\u0644 \u062a\u0646\u0641\u0633 \u0628\u0627 \u0633\u0637\u062d \u06f1\u06f6 mg/dL) \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u062a\u062d\u062a \u062f\u0631\u0645\u0627\u0646 \u0628\u0627 \u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645: \u0642\u0637\u0639 \u0641\u0648\u0631\u06cc \u0633\u0648\u0644\u0641\u0627\u062a + \u067e\u0627\u062f\u0632\u0647\u0631 \u06a9\u0644\u0633\u06cc\u0645 \u06af\u0644\u0648\u06a9\u0648\u0646\u0627\u062a.",
   "interpretation": "\u0633\u0648\u0644\u0641\u0627\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u062f\u0631 \u0633\u0637\u0648\u062d \u0628\u0627\u0644\u0627\u06cc \u062f\u0631\u0645\u0627\u0646\u06cc (>\u06f7 mEq/L \u2248 8.4-10 mg/dL \u0628\u0631\u0627\u06cc \u0634\u0631\u0648\u0639 \u0631\u0641\u0644\u06a9\u0633\u200c\u0647\u0627\u06cc \u0627\u0632\u062f\u0633\u062a\u200c\u0631\u0641\u062a\u0647 \u0648 \u0628\u0627\u0644\u0627\u062a\u0631 \u0628\u0631\u0627\u06cc \u062e\u0641\u06af\u06cc \u062a\u0646\u0641\u0633\u06cc) \u0633\u0645 \u0627\u0633\u062a\u061b \u062f\u0631 \u062a\u0638\u0627\u0647\u0631\u0627\u062a \u0639\u0636\u0644\u0627\u0646\u06cc-\u062a\u0646\u0641\u0633\u06cc \u0628\u0627\u06cc\u062f \u0641\u0648\u0631\u0627\u064b \u0633\u0648\u0644\u0641\u0627\u062a \u0642\u0637\u0639 \u0634\u0648\u062f \u062a\u0627 \u0645\u0646\u0627\u0628\u0639 \u0648\u0631\u0648\u062f\u06cc \u0645\u062a\u0648\u0642\u0641 \u0634\u0648\u062f \u0648 \u06a9\u0644\u0633\u06cc\u0645 \u06af\u0644\u0648\u06a9\u0648\u0646\u0627\u062a \u0648\u0631\u06cc\u062f\u06cc (\u06f1 \u06af\u0631\u0645 \u062f\u0631 \u06f1\u06f0\u066a \u062d\u062c\u0645\u06cc/\u062f\u0642\u06cc\u0642\u06cc \u0637\u06cc \u06f5-\u06f1\u06f0 \u062f\u0642\u06cc\u0642\u0647) \u0628\u0647\u200c\u0639\u0646\u0648\u0627\u0646 \u067e\u0627\u062f\u0632\u0647\u0631 \u0622\u0646\u062a\u0627\u06af\u0648\u0646\u06cc\u0633\u062a \u0645\u0633\u062a\u0642\u06cc\u0645 \u062f\u0627\u062f\u0647 \u0634\u0648\u062f\u061b \u0627\u062f\u0627\u0645\u0647\u0654 \u0633\u0648\u0644\u0641\u0627\u062a \u0647\u0631\u06af\u0632 \u062a\u0648\u062c\u06cc\u0647\u200c\u0634\u062f\u0647 \u0646\u06cc\u0633\u062a \u0648 \u0645\u0633\u062f\u0648\u062f\u06a9\u0646\u0646\u062f\u0647\u200c\u0647\u0627\u06cc \u06a9\u0627\u0646\u0627\u0644 \u06a9\u0644\u0633\u06cc\u0645\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0648\u0631\u06cc\u062a \u067e\u0627\u062f\u0632\u0647\u0631 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u0646\u06cc\u0633\u062a\u0646\u062f.",
   "reasons": ["\u0645\u0633\u062f\u0648\u062f\u06a9\u0646\u0646\u062f\u0647\u200c\u0647\u0627\u06cc \u06a9\u0644\u0633\u06cc\u0645\u06cc \u067e\u0627\u062f\u0632\u0647\u0631 \u0627\u0646\u062a\u062e\u0627\u0628\u06cc \u0645\u0633\u0645\u0648\u0645\u06cc\u062a \u0645\u0646\u06cc\u0632\u06cc\u0645 \u0646\u06cc\u0633\u062a\u0646\u062f.", "\u0642\u0637\u0639 \u0633\u0648\u0644\u0641\u0627\u062a \u0648 \u062f\u0627\u062f\u0646 \u06a9\u0644\u0633\u06cc\u0645 \u06af\u0644\u0648\u06a9\u0648\u0646\u0627\u062a \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0633\u0648\u0644\u0641\u0627\u062a \u062f\u0631 \u062a\u0638\u0627\u0647\u0631\u0627\u062a \u0633\u0645\u06cc \u0627\u0634\u062a\u0628\u0627\u0647 \u0627\u0633\u062a.", "\u0627\u062f\u0627\u0645\u0647\u0654 \u0633\u0648\u0644\u0641\u0627\u062a \u0628\u0627 \u0647\u0631 \u062f\u0627\u0631\u0648\u06cc\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0641\u0648\u0631\u06cc\u062a \u0642\u0627\u0628\u0644 \u062f\u0641\u0627\u0639 \u0646\u06cc\u0633\u062a."],
  },
  (28, 37): {
   "topic": "migrainePregContraindicated",
   "lead": "\u062f\u0631 \u0645\u06cc\u06af\u0631\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc\u060c \u0627\u0631\u06af\u0648\u062a\u0627\u0645\u06cc\u0646 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0627\u062b\u0631 \u0627\u0646\u0642\u0628\u0627\u0636\u200c\u062f\u0647\u0646\u062f\u0647\u0654 \u0639\u0631\u0648\u0642\u06cc-\u0631\u062d\u0645\u06cc \u0645\u0646\u0639 \u0645\u0635\u0631\u0641 \u0645\u0637\u0644\u0642 \u062f\u0627\u0631\u062f.",
   "interpretation": "\u062f\u0627\u0631\u0648\u0647\u0627\u06cc \u062d\u0645\u0644\u0647\u200c\u0627\u06cc \u0645\u06cc\u06af\u0631\u0646 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627\u06cc\u062f \u0628\u0627 \u0627\u062e\u062a\u0644\u0627\u0641 \u0627\u06cc\u0645\u0646\u06cc \u0627\u0646\u062a\u062e\u0627\u0628 \u0634\u0648\u0646\u062f\u061b \u0627\u0633\u062a\u0627\u0645\u06cc\u0646\u0648\u0641\u0646 \u062e\u0637 \u0645\u0642\u062f\u0645 \u0627\u0633\u062a\u060c \u0633\u0648\u0645\u0627\u062a\u0648\u062a\u0631\u06cc\u067e\u062a\u0627\u0646 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc \u0642\u0627\u0628\u0644\u200c\u0642\u0628\u0648\u0644\u06cc \u062f\u0627\u0631\u062f\u060c \u062f\u0627\u0631\u0648\u0647\u0627\u06cc \u0636\u062f\u0627\u0644\u062a\u0647\u0627\u0628 \u063a\u06cc\u0631\u0627\u0633\u062a\u0631\u0648\u0626\u06cc\u062f\u06cc \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u062f\u0648\u0645 \u0645\u062d\u062f\u0648\u062f \u0648 \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u0633\u0648\u0645 \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f \u0648 \u0645\u062e\u062f\u0631\u0647\u0627 \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u06a9\u0648\u062a\u0627\u0647\u200c\u0645\u062f\u062a \u0628\u0627 \u0627\u062d\u062a\u06cc\u0627\u0637 \u0645\u0635\u0631\u0641 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f\u061b \u0648\u0644\u06cc \u0627\u0631\u06af\u0648\u062a\u0627\u0645\u06cc\u0646 \u0628\u0647\u200c\u0639\u0644\u062a \u0642\u0627\u0628\u0644\u06cc\u062a \u0627\u06cc\u062c\u0627\u062f \u0627\u0646\u0642\u0628\u0627\u0636 \u0631\u062d\u0645\u06cc (\u0627\u062b\u0631 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u06a9) \u0648 \u06a9\u0627\u0647\u0634 \u062c\u0631\u06cc\u0627\u0646 \u062e\u0648\u0646 \u0631\u062d\u0645\u06cc-\u062c\u0641\u062a\u06cc\u060c \u062f\u0631 \u062a\u0645\u0627\u0645 \u062f\u0648\u0631\u0627\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0646\u0639 \u0645\u0635\u0631\u0641 \u0645\u0637\u0644\u0642 \u062f\u0627\u0631\u062f.",
   "reasons": ["\u0633\u0648\u0645\u0627\u062a\u0648\u062a\u0631\u06cc\u067e\u062a\u0627\u0646 \u062f\u0631 \u0635\u0648\u0631\u062a \u0644\u0632\u0648\u0645 \u0628\u0627 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u0628\u0627\u0644\u06cc\u0646\u06cc \u0645\u0646\u0627\u0633\u0628 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0642\u0627\u0628\u0644\u200c\u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a.", "\u0645\u062e\u062f\u0631\u0647\u0627 \u062f\u0631 \u062d\u0645\u0644\u0627\u062a \u0634\u062f\u06cc\u062f \u0628\u0647\u200c\u0635\u0648\u0631\u062a \u06a9\u0648\u062a\u0627\u0647\u200c\u0645\u062f\u062a \u0628\u0627 \u0627\u062d\u062a\u06cc\u0627\u0637 \u062a\u062c\u0648\u06cc\u0632 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f.", "\u0627\u0631\u06af\u0648\u062a\u0627\u0645\u06cc\u0646 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u0627\u0646\u0642\u0628\u0627\u0636 \u0639\u0631\u0648\u0642\u06cc \u0648 \u0627\u062b\u0631 \u0627\u06a9\u0633\u06cc\u200c\u062a\u0648\u0633\u06cc\u06a9 \u0631\u062d\u0645\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0622\u0633\u067e\u06cc\u0631\u06cc\u0646 \u0628\u0647\u200c\u0634\u06a9\u0644 \u0645\u062d\u062f\u0648\u062f \u062f\u0631 \u0633\u0647\u200c\u0645\u0627\u0647\u0647\u0654 \u062f\u0648\u0645 \u0642\u0627\u0628\u0644\u200c\u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0633\u062a \u0648 \u0645\u0646\u0639 \u0645\u0637\u0644\u0642 \u0627\u06cc\u0646 \u067e\u0631\u0633\u0634 \u0646\u06cc\u0633\u062a."],
  },
  (28, 38): {
   "topic": "endometriosisDiagnosis",
   "lead": "\u062f\u0631 \u062f\u06cc\u0633\u0645\u0646\u0648\u0631\u0647 \u0648 \u0646\u0627\u0632\u0627\u06cc\u06cc \u0627\u0648\u0644\u06cc\u0647\u060c \u06cc\u0627\u0641\u062a\u0647\u200c\u0627\u06cc \u06a9\u0647 \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u0631\u0627 \u0642\u0637\u0639\u06cc\u200c\u062a\u0631 \u0645\u0637\u0631\u062d \u0645\u06cc\u200c\u06a9\u0646\u062f \u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0636\u0627\u06cc\u0639\u0627\u062a \u062f\u0631 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u0627\u0633\u062a.",
   "interpretation": "\u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u0628\u0647\u200c\u0645\u0639\u0646\u0627\u06cc \u0648\u062c\u0648\u062f \u0628\u0627\u0641\u062a \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0627\u0644 \u062e\u0627\u0631\u062c \u0627\u0632 \u062d\u0641\u0631\u0647\u0654 \u0631\u062d\u0645 \u0627\u0633\u062a \u0648 \u0647\u0631\u0686\u0646\u062f \u0639\u0644\u0627\u06cc\u0645 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0645\u062b\u0644 \u062f\u06cc\u0633\u0645\u0646\u0648\u0631\u0647\u060c \u062f\u06cc\u0633\u067e\u0627\u0631\u0648\u0646\u06cc\u060c \u0646\u0627\u0632\u0627\u06cc\u06cc \u0648 \u0646\u062f\u0648\u0644\u0627\u0631\u06cc\u062a\u0647 \u0644\u06cc\u06af\u0627\u0645\u0627\u0646\u200c\u0647\u0627\u06cc \u06cc\u0648\u062a\u0631\u0648\u0633\u0627\u06a9\u0631\u0627\u0644 \u0634\u06a9 \u0631\u0627 \u0628\u0627\u0644\u0627 \u0645\u06cc\u200c\u0628\u0631\u0646\u062f\u060c \u0647\u06cc\u0686\u200c\u06a9\u062f\u0627\u0645 \u0642\u0637\u0639\u06cc \u0646\u06cc\u0633\u062a\u0646\u062f\u061b \u062a\u0646\u0647\u0627 \u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0636\u0627\u06cc\u0639\u0627\u062a \u0645\u0639\u0645\u0648\u0644 \u067e\u0631\u06cc\u062a\u0648\u0646\u0647\u200c\u0622\u0644/\u062a\u062e\u0645\u062f\u0627\u0646\u06cc \u062d\u06cc\u0646 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc (\u0648 \u062f\u0631 \u062d\u0627\u0644\u062a \u0627\u06cc\u062f\u0647\u200c\u0622\u0644 \u067e\u0627\u062a\u0648\u0644\u0648\u0698\u06cc \u0646\u0645\u0648\u0646\u0647) \u062a\u0634\u062e\u06cc\u0635 \u0642\u0637\u0639\u06cc \u0631\u0627 \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0628\u0632\u0631\u06af\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0641\u0642\u0637 \u062f\u0631 \u0635\u0648\u0631\u062a \u062a\u0634\u06a9\u06cc\u0644 \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0645\u0627 \u062f\u06cc\u062f\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645 \u0636\u0627\u06cc\u0639\u0627\u062a \u062d\u06cc\u0646 \u0644\u0627\u067e\u0627\u0631\u0648\u0633\u06a9\u0648\u067e\u06cc \u062a\u0623\u06cc\u06cc\u062f \u0642\u0637\u0639\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u062f\u06cc\u0633\u067e\u0627\u0631\u0648\u0646\u06cc \u0634\u06a9\u0627\u06cc\u062a \u0631\u0627\u06cc\u062c \u0627\u0645\u0627 \u063a\u06cc\u0631\u0627\u062e\u062a\u0635\u0627\u0635\u06cc \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0632 \u0627\u0633\u062a.", "\u0628\u0632\u0631\u06af\u06cc \u062a\u062e\u0645\u062f\u0627\u0646 \u0641\u0642\u0637 \u062f\u0631 \u0622\u0646\u062f\u0648\u0645\u062a\u0631\u06cc\u0648\u0645\u0627 \u0631\u062e \u0645\u06cc\u200c\u062f\u0647\u062f \u0648 \u0639\u0645\u0648\u0645\u06cc\u062a \u0646\u062f\u0627\u0631\u062f.", "\u0646\u062f\u0648\u0644\u0627\u0631\u06cc\u062a\u0647 \u0644\u06cc\u06af\u0627\u0645\u0627\u0646\u200c\u0647\u0627\u06cc \u06cc\u0648\u062a\u0631\u0648\u0633\u0627\u06a9\u0631\u0627\u0644 \u0628\u0647 \u0644\u062d\u0627\u0638 \u0628\u0627\u0644\u06cc\u0646\u06cc \u0642\u0648\u06cc \u0627\u0633\u062a \u0627\u0645\u0627 \u0627\u0632 \u0645\u0634\u0627\u0647\u062f\u0647\u0654 \u0645\u0633\u062a\u0642\u06cc\u0645 \u06a9\u0645\u062a\u0631 \u0627\u0633\u062a."],
  },
  (28, 39): {
   "topic": "transverseLieProm",
   "lead": "\u062c\u0646\u06cc\u0646 \u0639\u0631\u0636\u06cc + \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u0654 \u0622\u0645\u0646\u06cc\u0648\u062a\u06cc\u06a9 \u062f\u0631 \u06f3\u06f5 \u0647\u0641\u062a\u0647\u0654 \u0686\u0646\u062f\u0642\u0644\u0648\u06cc\u06cc: \u0633\u0632\u0627\u0631\u06cc\u0646 \u0628\u0647\u200c\u062e\u0627\u0637\u0631 \u062e\u0637\u0631 \u067e\u0631\u0648\u0644\u0627\u067e\u0633 \u0628\u0646\u062f \u0646\u0627\u0641.",
   "interpretation": "\u062f\u0631 \u0646\u0645\u0627\u06cc \u0639\u0631\u0636\u06cc\u060c \u0639\u0636\u0648 \u0646\u0645\u0627\u06cc\u0634 \u0631\u0648\u06cc \u0645\u062f\u062e\u0644 \u0644\u06af\u0646 \u0642\u0631\u0627\u0631 \u0646\u0645\u06cc\u200c\u06af\u06cc\u0631\u062f \u0648 \u067e\u0633 \u0627\u0632 \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647 \u062e\u0637\u0631 \u067e\u0631\u0648\u0644\u0627\u067e\u0633 (\u0642\u0641\u0644\u200c\u0634\u062f\u0646) \u0628\u0646\u062f \u0646\u0627\u0641 \u0634\u062f\u06cc\u062f \u0627\u0633\u062a\u061b \u0632\u0627\u06cc\u0645\u0627\u0646 \u0648\u0627\u0698\u06cc\u0646\u0627\u0644 \u0645\u0645\u06a9\u0646 \u0646\u06cc\u0633\u062a \u0648 \u0628\u0647\u200c\u0645\u062d\u0636 \u067e\u0627\u0631\u0647\u200c\u0634\u062f\u0646 \u067e\u0631\u062f\u0647 \u0628\u0627\u06cc\u062f \u0641\u0648\u0631\u0627\u064b \u0628\u0627 \u0633\u0632\u0627\u0631\u06cc\u0646 \u062e\u062a\u0645 \u0634\u0648\u062f. \u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u062a\u062d\u062a \u0646\u0638\u0631 \u062f\u0631 \u062d\u0636\u0648\u0631 PROM \u06cc\u0627 \u0686\u0631\u062e\u0634 \u062e\u0627\u0631\u062c\u06cc \u062f\u0631 \u0627\u06cc\u0646 \u0634\u0631\u0627\u06cc\u0637 \u0648 \u0631\u06cc\u0633\u06a9 \u067e\u0631\u0648\u0644\u0627\u067e\u0633 \u067e\u0630\u06cc\u0631\u0641\u062a\u0646\u06cc \u0646\u06cc\u0633\u062a \u0648 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0637\u0628\u06cc\u0639\u06cc \u0628\u0647 \u0647\u06cc\u0686 \u0631\u0648\u06cc \u0628\u0627 \u0646\u0645\u0627\u06cc \u0639\u0631\u0636\u06cc \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647\u200c\u0647\u0627 \u0627\u0646\u062c\u0627\u0645 \u0646\u0645\u06cc\u200c\u0634\u0648\u062f.",
   "reasons": ["\u0646\u06af\u0647\u200c\u062f\u0627\u0634\u062a\u0646 \u062a\u0627 \u06f3\u06f7 \u0647\u0641\u062a\u0647 \u0628\u0627 PROM \u0642\u0637\u0639\u06cc \u0648 \u0646\u0645\u0627\u06cc \u0639\u0631\u0636\u06cc \u062e\u0637\u0631 \u067e\u0631\u0648\u0644\u0627\u067e\u0633 \u0631\u0627 \u0628\u0647 \u062f\u0646\u0628\u0627\u0644 \u062f\u0627\u0631\u062f.", "\u0686\u0631\u062e\u0634 \u062e\u0627\u0631\u062c\u06cc \u0633\u0641\u0627\u0644\u06cc\u06a9 \u067e\u0633 \u0627\u0632 \u067e\u0627\u0631\u06af\u06cc \u067e\u0631\u062f\u0647 \u0628\u0627 \u0646\u0645\u0627\u06cc \u0639\u0631\u0636\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a.", "\u0633\u0632\u0627\u0631\u06cc\u0646 \u062f\u0631 \u0646\u0645\u0627\u06cc \u0639\u0631\u0636\u06cc \u0628\u0627 PROM \u0627\u0642\u062f\u0627\u0645 \u062c\u0628\u0631\u0627\u0646\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0632\u0627\u06cc\u0645\u0627\u0646 \u0637\u0628\u06cc\u0639\u06cc \u0628\u0627 \u0646\u0645\u0627\u06cc \u0639\u0631\u0636\u06cc \u0648 PROM \u062c\u0627\u06cc\u06af\u0627\u0647\u06cc \u0646\u062f\u0627\u0631\u062f."],
  },
  (28, 40): {
   "topic": "postpartumPeManagement",
   "lead": "\u062a\u0646\u06af\u06cc\u200c\u0646\u0641\u0633 \u0648 \u062a\u0627\u06a9\u06cc\u200c\u06a9\u0627\u0631\u062f\u06cc \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0627 BMI \u0628\u0627\u0644\u0627 \u0648 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0627\u062e\u06cc\u0631: \u0622\u0645\u0628\u0648\u0644\u06cc \u0631\u06cc\u0648\u06cc \u0645\u062d\u062a\u0645\u0644\u061b \u0634\u0631\u0648\u0639 \u0647\u067e\u0627\u0631\u06cc\u0646 \u062a\u062c\u0631\u0628\u06cc \u0648 \u0627\u0639\u0632\u0627\u0645 \u0641\u0648\u0631\u06cc \u0628\u0647 \u0628\u06cc\u0645\u0627\u0631\u0633\u062a\u0627\u0646.",
   "interpretation": "\u062f\u0648\u0631\u0627\u0646 \u067e\u0633 \u0627\u0632 \u0632\u0627\u06cc\u0645\u0627\u0646 \u0628\u0647\u200c\u0648\u06cc\u0698\u0647 \u067e\u0633 \u0627\u0632 \u0633\u0632\u0627\u0631\u06cc\u0646 \u0648 \u0628\u0627 \u0686\u0627\u0642\u06cc\u060c \u067e\u0646\u062c\u0631\u0647\u0654 \u067e\u0631\u062e\u0637\u0631 \u062a\u0631\u0648\u0645\u0628\u0648\u0622\u0645\u0628\u0648\u0644\u06cc \u0648\u0631\u06cc\u062f\u06cc \u0627\u0633\u062a\u061b \u062a\u0646\u06af\u06cc\u200c\u0646\u0641\u0633 \u062d\u0627\u062f \u0628\u0627 \u062a\u0627\u06a9\u06cc\u200c\u067e\u0646\u0647 (RR=30) \u0648 \u062a\u0627\u06a9\u06cc\u200c\u06a9\u0627\u0631\u062f\u06cc (PR=110) \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u062a\u0627\u0632\u0647 \u0633\u0632\u0627\u0631\u06cc\u0646\u200c\u0634\u062f\u0647 \u0628\u0627\u06cc\u062f \u0622\u0645\u0628\u0648\u0644\u06cc \u0631\u06cc\u0648\u06cc \u0631\u0627 \u062f\u0631 \u0646\u0638\u0631 \u0628\u06af\u06cc\u0631\u062f. \u062f\u0631 \u0634\u0631\u0627\u06cc\u0637 \u0633\u0631\u067e\u0627\u06cc\u06cc (\u062f\u0631\u0645\u0627\u0646\u06af\u0627\u0647) \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644\u06cc\u0647\u0654 \u062f\u0631\u0633\u062a\u060c \u0634\u0631\u0648\u0639 \u062a\u062c\u0631\u0628\u06cc \u0647\u067e\u0627\u0631\u06cc\u0646 \u0648 \u0633\u067e\u0633 \u0627\u0639\u0632\u0627\u0645 \u0628\u0647 \u0628\u06cc\u0645\u0627\u0631\u0633\u062a\u0627\u0646 \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0648 \u062a\u0623\u06cc\u06cc\u062f \u062a\u0635\u0648\u06cc\u0631\u06cc \u0627\u0633\u062a\u061b \u062f\u06af\u0632\u0627\u0645\u062a\u0627\u0632\u0648\u0646 \u062c\u0627\u06cc\u06af\u0627\u0647 \u0646\u062f\u0627\u0631\u062f \u0648 \u0622\u0632\u0645\u0627\u06cc\u0634\u200c\u0647\u0627\u06cc \u062a\u0635\u0648\u06cc\u0631\u0628\u0631\u062f\u0627\u0631\u06cc \u062a\u0634\u062e\u06cc\u0635\u06cc \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631\u0633\u062a\u0627\u0646 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f \u0646\u0647 \u062f\u0631 \u062f\u0631\u0645\u0627\u0646\u06af\u0627\u0647.",
   "reasons": ["\u062f\u06af\u0632\u0627\u0645\u062a\u0627\u0632\u0648\u0646 \u062f\u0631 \u0627\u06cc\u0646 \u0634\u0631\u0627\u06cc\u0637 \u0627\u0636\u0637\u0631\u0627\u0631\u06cc \u0646\u0642\u0634 \u062f\u0631\u0645\u0627\u0646\u06cc \u0646\u062f\u0627\u0631\u062f.", "\u0634\u0631\u0648\u0639 \u0647\u067e\u0627\u0631\u06cc\u0646 \u0648 \u0627\u0639\u0632\u0627\u0645 \u0641\u0648\u0631\u06cc \u0628\u0647 \u0628\u06cc\u0645\u0627\u0631\u0633\u062a\u0627\u0646 \u0628\u0631\u0627\u06cc \u0627\u0631\u0632\u06cc\u0627\u0628\u06cc \u0627\u0636\u0637\u0631\u0627\u0631\u06cc \u0622\u0645\u0628\u0648\u0644\u06cc \u062f\u0631\u0633\u062a \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "CTPA \u062f\u0631 \u0627\u06cc\u0646 \u0645\u0631\u062d\u0644\u0647 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631\u0633\u062a\u0627\u0646 \u067e\u0633 \u0627\u0632 \u0627\u0639\u0632\u0627\u0645 \u0627\u0646\u062c\u0627\u0645 \u0645\u06cc\u200c\u0634\u0648\u062f.", "\u0627\u0633\u06a9\u0646 \u062a\u0647\u0648\u06cc\u0647-\u067e\u0631\u0641\u06cc\u0648\u0698\u0646 \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646 \u0627\u0633\u062a \u0648 \u0627\u0642\u062f\u0627\u0645 \u0627\u0648\u0644\u06cc\u0647\u0654 \u0627\u06cc\u0646 \u0634\u0631\u0627\u06cc\u0637 \u0646\u06cc\u0633\u062a."],
  },
  (28, 41): {
   "topic": "\u0633\u06cc\u0641\u0644\u06cc\u0633PregPenicillin",
   "lead": "\u0633\u06cc\u0641\u0644\u06cc\u0633 \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0627 \u062d\u0633\u0627\u0633\u06cc\u062a \u0628\u0647 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646: \u062a\u0646\u0647\u0627 \u062f\u0631\u0645\u0627\u0646 \u0645\u0624\u06cc\u062f \u0628\u0631\u0627\u06cc \u062c\u0646\u06cc\u0646 \u0628\u0646\u0632\u0627\u062a\u06cc\u0646 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u0627\u0633\u062a\u061b \u067e\u0633 \u0627\u0632 \u062d\u0633\u0627\u0633\u06cc\u062a\u200c\u0632\u062f\u0627\u06cc\u06cc \u0647\u0645\u0627\u0646 \u0631\u0627 \u0628\u062f\u0647.",
   "interpretation": "\u062a\u0646\u0647\u0627 \u0631\u0698\u06cc\u0645 \u0627\u062b\u0628\u0627\u062a\u200c\u0634\u062f\u0647 \u0628\u0631\u0627\u06cc \u062c\u0644\u0648\u06af\u06cc\u0631\u06cc \u0627\u0632 \u06cc\u0627 \u062f\u0631\u0645\u0627\u0646 \u0633\u06cc\u0641\u0644\u06cc\u0633 \u0645\u0627\u062f\u0631\u0632\u0627\u062f\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0628\u0646\u0632\u0627\u062a\u06cc\u0646 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 G \u0627\u0633\u062a\u061b \u062c\u0627\u06cc\u06af\u0632\u06cc\u0646\u200c\u0647\u0627\u06cc \u0645\u062b\u0644 \u0633\u0641\u062a\u0631\u06cc\u0627\u06a9\u0633\u0648\u0646\u060c \u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u0648 \u062f\u0627\u06a9\u0633\u06cc\u200c\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u06cc\u0627 \u062f\u0627\u062f\u0647\u200c\u0647\u0627\u06cc \u06a9\u0627\u0641\u06cc \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0646\u062f\u0627\u0631\u0646\u062f \u06cc\u0627 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f (\u062f\u0627\u06a9\u0633\u06cc\u200c\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646) \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639\u200c\u0627\u0646\u062f \u0648 \u0646\u0645\u06cc\u200c\u062a\u0648\u0627\u0646\u0646\u062f \u0627\u0632 \u0639\u0628\u0648\u0631 \u062c\u0641\u062a\u06cc \u0639\u0641\u0648\u0646\u062a \u0628\u0647\u200c\u0637\u0648\u0631 \u0642\u0627\u0628\u0644\u200c\u0627\u0639\u062a\u0645\u0627\u062f \u067e\u06cc\u0634\u200c\u06af\u06cc\u0631\u06cc \u06a9\u0646\u0646\u062f\u061b \u0628\u0646\u0627\u0628\u0631\u0627\u06cc\u0646 \u062f\u0631 \u0628\u06cc\u0645\u0627\u0631 \u0622\u0644\u0631\u0698\u06cc\u06a9 \u0628\u0647 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646\u060c \u062a\u0648\u0635\u06cc\u0647\u0654 \u0627\u0633\u062a\u0627\u0646\u062f\u0627\u0631\u062f \u062d\u0633\u0627\u0633\u06cc\u062a\u200c\u0632\u062f\u0627\u06cc\u06cc \u0648 \u0633\u067e\u0633 \u062a\u062c\u0648\u06cc\u0632 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u062a\u062d\u062a \u067e\u0627\u06cc\u0634 \u0627\u0633\u062a.",
   "reasons": ["\u062d\u0633\u0627\u0633\u06cc\u062a\u200c\u0632\u062f\u0627\u06cc\u06cc \u0648 \u062a\u062c\u0648\u06cc\u0632 \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u062a\u0646\u0647\u0627 \u0645\u0633\u06cc\u0631 \u0645\u0624\u06cc\u062f \u062f\u0631 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u0633\u062a\u061b \u067e\u0627\u0633\u062e \u0635\u062d\u06cc\u062d.", "\u0633\u0641\u062a\u0631\u06cc\u0627\u06a9\u0633\u0648\u0646 \u0628\u0647\u200c\u062e\u0648\u0628\u06cc \u067e\u0646\u06cc\u200c\u0633\u06cc\u0644\u06cc\u0646 \u0628\u0631\u0627\u06cc \u0633\u06cc\u0641\u0644\u06cc\u0633 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0627\u062b\u0628\u0627\u062a\u200c\u0646\u0634\u062f\u0647 \u0627\u0633\u062a.", "\u0627\u0631\u06cc\u062a\u0631\u0648\u0645\u0627\u06cc\u0633\u06cc\u0646 \u0627\u0632 \u062c\u0641\u062a \u0628\u0647 \u0642\u062f\u0631 \u06a9\u0627\u0641\u06cc \u0639\u0628\u0648\u0631 \u0646\u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0645\u0624\u06cc\u062f \u0646\u06cc\u0633\u062a.", "\u062f\u0627\u06a9\u0633\u06cc\u200c\u0633\u0627\u06cc\u06a9\u0644\u06cc\u0646 \u0628\u0647\u200c\u062e\u0648\u062f\u06cc\u200c\u062e\u0648\u062f \u062f\u0631 \u062a\u0645\u0627\u0645 \u062f\u0648\u0631\u0627\u0646 \u0628\u0627\u0631\u062f\u0627\u0631\u06cc \u0645\u0645\u0646\u0648\u0639 \u0627\u0633\u062a."],
  },
}
